  str_item_7000200 = "Lupa",
  str_item_7000201 = "Pluma",
  str_item_7000202 = "Informe de calificaciones",
  str_item_7000203 = "Palo señalador",
  str_item_7000204 = "Precedente Legal (1)",
  str_item_7000205 = "Informe de Investigación Confidencial",
  str_item_7000206 = "Precedente Legal (2)",
  str_item_intro_7000200 = "Una lupa de diseño único con colores distintivos, herramienta indispensable en las investigaciones.",
  str_item_intro_7000201 = "Una brillante pluma dorada que se siente pesada en tu mano.",
  str_item_intro_7000202 = "Un informe de calificaciones perfecto de la Academia Dawn, que demuestra un rendimiento excepcional.",
  str_item_intro_7000203 = "Una caña escondida en un rincón, aparentemente discreta, evocando recuerdos de la infancia de Irridon.",
  str_item_intro_7000204 = "Un precedente dejado por el Juez Rodell Novek, reflejando su propia naturaleza fría e implacable.",
  str_item_intro_7000205 = "Un informe de investigación confidencial escrito por el padre de Irridon, mucho antes del juicio del testamento del Barón, él conocía las intenciones ocultas detrás del testamento.",
  str_item_intro_7000206 = "Un precedente dejado por el juez Rodell Novek, con un veredicto que resultó en la erradicación de una familia entera.",
  str_item_sub_intro_7000200 = "\"¿Es solo mi imaginación, o esta lupa realmente está llamando mi nombre? Bueno, eso no puede ser posible. Pero esta lupa se ve extrañamente familiar... ¿Podría ser mía? ¿Qué me está pasando? ¿Cómo es que no puedo recordar algo así?\"",
  str_item_sub_intro_7000201 = "\"¿Por qué es así? ¿Por qué nunca puedo ganar su aprobación, ya sea de mi padre o de mis compañeros...\"",
  str_item_sub_intro_7000202 = "\"¿Acaso no di lo mejor de mí...?\"",
  str_item_sub_intro_7000203 = "\"¿Cuánto esfuerzo se necesita para olvidar esos momentos sombríos de mi infancia?\"",
  str_item_sub_intro_7000204 = "\"¿Debería llevar adelante la mentalidad detrás de este fallo...\"",
  str_item_sub_intro_7000205 = "\"¿Q-Qué he hecho...?\"",
  str_item_sub_intro_7000206 = "\"Yo creo... tengo mi propia respuesta.\"",
  str_item_7000300 = "Obtener Evidencia",
  str_item_7000301 = "Obtener Testimonio",
  str_item_7000302 = "Obtener Evidencia",
  str_item_7000303 = "Obtener Testimonio",
  str_item_7000304 = "Obtener Estatua",
  str_item_7000305 = "Obtener Estatua",
  str_item_7000306 = "Obtener Evidencia",
  str_item_7000307 = "Obtener Evidencia",
  str_item_7000308 = "Obtener Testimonio",
  str_item_7000309 = "Obtener Testimonio",
  str_item_7000310 = "Obtener Estatua",
  str_item_7000311 = "Obtener Estatua",
  str_item_7000312 = "Obtener Evidencia",
  str_item_7000313 = "Obtener Evidencia",
  str_item_7000314 = "Obtener Testimonio",
  str_item_7000315 = "Obtener Testimonio",
  str_item_7000316 = "Obtener Estatua",
  str_item_7000317 = "Obtener Estatua",
  str_item_7000318 = "Peso dorado",
  str_item_7000319 = "Peso dorado",
  str_item_7000320 = "Peso dorado",
  str_item_intro_7000300 = "Nodirri no parece tener el emblema en ella.",
  str_item_intro_7000301 = "Un testimonio de un miembro del consejo estudiantil: La familia de Pam está enfrentando dificultades económicas.",
  str_item_intro_7000302 = "Existe una relación competitiva entre Nodirri y Pam.",
  str_item_intro_7000303 = "Testimonio del viejo portero: Nodirri visitó la sala de autoestudio antes.",
  str_item_intro_7000304 = "Delito contra la propiedad",
  str_item_intro_7000305 = "Delito contra el Orden Público",
  str_item_intro_7000306 = "Se ha confirmado que el testamento del abuelo es auténtico.",
  str_item_intro_7000307 = "Las huellas dactilares de Jerry se encontraron en las herramientas que el abuelo utilizó para suicidarse.",
  str_item_intro_7000308 = "Testimonio del vecino: El abuelo mencionó querer pasar todo a su nieta.",
  str_item_intro_7000309 = "Testimonio del testigo: No se observaron anomalías cuando el abuelo redactó su testamento.",
  str_item_intro_7000310 = "Falsificación de documentos",
  str_item_intro_7000311 = "Ley de Herencia Testamentaria",
  str_item_intro_7000312 = "El emblema de la familia Pyrrhus encontrado en la habitación de Gautier.",
  str_item_intro_7000313 = "Maldiciones escritas por Mirren Gautier en su cuaderno de dibujo.",
  str_item_intro_7000314 = "La familia Gautier capturó a miembros de la familia Pyrrhus para experimentos.",
  str_item_intro_7000315 = "La familia Pyrrhus sigue investigando los Cristales Sanguíneos.",
  str_item_intro_7000316 = "Traición",
  str_item_intro_7000317 = "Delito de Difundir Rumores",
  str_item_intro_7000318 = "¡Evidencia encontrada para el caso de robo del Emblema Dawn!",
  str_item_intro_7000319 = "¡Evidencia encontrada para el caso del Testamento del Abuelo!",
  str_item_intro_7000320 = "¡Evidencia encontrada en el caso de traición de la familia Gautier!",
  str_item_sub_intro_7000300 = "Al escuchar el relato de Pam sobre el caso, Nodirri se enfurece visiblemente. Se acerca a Pam, lanzándole una ráfaga de preguntas sobre por qué la difamaría de esa manera. Para demostrar su inocencia, Nodirri permite voluntariamente que Irridon la registre y, como era de esperar, no se descubre nada incriminatorio.",
  str_item_sub_intro_7000301 = "En el camino hacia la sala de estudio, Irridon es abordado discretamente por un miembro del consejo estudiantil, quien comparte apasionadamente su perspectiva, \"¡La familia de Pam nunca fue una casa noble de alto rango y sus padres no han ocupado cargos públicos oficiales! Últimamente, parece que enfrentan dificultades financieras por alguna razón\".",
  str_item_sub_intro_7000302 = "En el tablón de anuncios de la escuela, Irridon encuentra un anuncio del Templo de Lumopolis: este año, han aceptado a dos monjas en formación, Pam y Nodirri. Sin embargo, solo una de ellas tendrá la oportunidad de permanecer en el templo.",
  str_item_sub_intro_7000303 = "Irridon llega a las cercanías de la sala de estudio y ve a un anciano portero durmiendo cerca. Claramente, el portero no ha olvidado a Irridon, ya que recibió ayuda de Irridon varias veces durante la escuela. El portero menciona que hoy, aparte de Pam, solo Nodirri entró a la sala de estudio. Le pareció extraño en ese momento por qué Nodirri usó un pañuelo para abrir la puerta. \"Tal vez es una maniática de los gérmenes; no le di mucha importancia en ese momento.\"",
  str_item_sub_intro_7000304 = "El robo de propiedad significativa, cuando la cantidad robada es sustancial, es castigado con una pena de prisión que va de tres a diez años y una multa.",
  str_item_sub_intro_7000305 = "Insultar públicamente o difamar intencionalmente a otros, en circunstancias graves, puede llevar a una pena de prisión de hasta tres años y una multa.",
  str_item_sub_intro_7000306 = "Jerry presenta el testamento que tiene en mano a Irridon y, después de una meticulosa comparación y análisis, Irridon confirma que el testamento del abuelo de Pam fue escrito por él mismo. En el testamento, el abuelo deja su título y riqueza a Jerry, declarando: \"He vivido lo suficiente y no tengo arrepentimientos\". Irridon presta especial atención a esta declaración, ya que parece que el abuelo insinuó su intención de suicidarse al escribir el testamento.",
  str_item_sub_intro_7000307 = "Irridon llega a la residencia del abuelo de Pam y descubre que él terminó su propia vida usando un pequeño cuchillo de frutas. Sin embargo, al inspeccionar de cerca el cuchillo, Irridon identifica las huellas dactilares de Jerry en él. Jerry explica que a menudo prepara comidas, por lo que tener sus huellas dactilares en los utensilios no es inusual. Irridon reevalúa la situación y confirma el suicidio del abuelo.",
  str_item_sub_intro_7000308 = "Irridon toca la puerta del vecino del abuelo, y el vecino le cuenta a Irridon que, aunque el abuelo a menudo lamentaba las insuficiencias de su hijo, frecuentemente presumía de su nieta. El abuelo incluso había declarado públicamente que tenía la intención de pasar su título y riqueza a su nieta, sin dejar nada para su hijo.",
  str_item_sub_intro_7000309 = "El testigo del testamento es un anciano sirviente bien educado. El viejo sirviente expresa un inmenso honor por ser invitado por el abuelo a ser testigo. Justo cuando las palabras salen de la boca del anciano sirviente, de repente siente que se expresó mal. Un poco avergonzado, el sirviente continúa explicando que no hubo nada inusual cuando el abuelo redactó el testamento y que había confirmado repetidamente que estas eran, de hecho, las verdaderas intenciones del abuelo.",
  str_item_sub_intro_7000310 = "La falsificación de documentos públicos o privados para actividades fraudulentas es punible con prisión de tres a diez años y una multa.",
  str_item_sub_intro_7000311 = "Los testamentos legalmente válidos deben ser seguidos en la distribución de bienes según su contenido.",
  str_item_sub_intro_7000312 = "Irridon se cuela en la habitación de la familia Gautier en Lumopolis Inferior, buscando cuidadosamente en ella. Para su sorpresa, descubre un emblema de la familia Pyrrhus escondido en un rincón. Ambas familias, Gautier y Pyrrhus, fueron exiliadas a Lumopolis Inferior debido al caso del Cristal Sanguíneo. ¿Es posible que estas dos familias estén colaborando en una rebelión? Irridon no se atreve a pensar más en ello. \"Pam también es miembro de la familia Pyrrhus...\"",
  str_item_sub_intro_7000313 = "Irridon se encuentra con otra casa en ruinas, y dentro, encuentra un cuaderno de dibujo firmado \"Mirren Gautier\". El libro contiene algunos patrones abstractos que Irridon encuentra difíciles de comprender. Irridon entrecierra los ojos, y entre los patrones, descubre una pequeña línea de texto: \"¿Por qué me tratas así... Por qué, ¡¿POR QUÉ?! Voy a tomar el control de mi propio destino de nuevo... incluso si eso significa que tengo que usar su fuerza.\"",
  str_item_sub_intro_7000314 = "Un extraño Eclipsite aparece repentinamente en la calle. Sin dudarlo, Irridon avanza y atraviesa el pecho del Eclipsite, dejándolo caer al suelo. Pero de repente, como si despertara de un aturdimiento, el Eclipsite levanta su mano en dirección a la multitud, luchando por decir algo. Irridon se acerca, escuchando los murmullos del Eclipsite: \"Gautier... buscando venganza... contra Pyrrhus... ellos... nos capturaron... para experimentar... están planeando... ¡una rebelión!\"",
  str_item_sub_intro_7000315 = "Mientras Irridon contempla su próximo movimiento para la investigación, un transeúnte harapiento se acerca discretamente. Afirma saber todo sobre los acontecimientos recientes en Baja Lumopolis, revelando que la familia Pyrrhus sigue investigando los Cristales Sanguíneos. Irridon pregunta por qué comparte esta información, y el transeúnte entreabre los labios, mostrando sus dientes oscurecidos y diciendo: \"¿Puedes llevarme de vuelta al Patio de Lumopolis?\"",
  str_item_sub_intro_7000316 = "Tramar deliberadamente o intentar derrocar el gobierno de Lumopolis resultará en una condena de por vida, con la posibilidad de pena de muerte en casos graves.",
  str_item_sub_intro_7000317 = "Difundir rumores falsos sobre otros intencionalmente puede llevar a un encarcelamiento de hasta un año y una multa.",
  str_item_sub_intro_7000318 = "Basándose en pruebas y declaraciones de testigos, Irridon deduce que Nodirri es el culpable de robar el Emblema Dawn.",
  str_item_sub_intro_7000319 = "Consideras válido el testamento, y el sirviente Jerry heredará el título y toda la riqueza del abuelo de Pam...",
  str_item_sub_intro_7000320 = "Has recopilado pruebas y testimonios exhaustivos que confirman que Mirren Gautier secuestró a miembros de la casa Pyrrhus para experimentar con ellos y tenía intenciones rebeldes.",
  str_item_7000400 = "Llave antigua",
  str_item_7000401 = "Galletas de Dayna",
  str_item_7000402 = "Plano para Nuevo Hogar",
  str_item_7000403 = "Trombón Elegante",
  str_item_7000404 = "Nueva partitura musical",
  str_item_7000405 = "Retrato de Dayna",
  str_item_7000406 = "Retrato de Robyn",
  str_item_7000407 = "Dama en el retrato del tetera",
  str_item_7000408 = "Retrato del delfín blanco",
  str_item_intro_7000400 = "Llave del ático que le dio su tía a Connolly. Úsala con cuidado para que el antiguo cerrojo no chirríe y moleste a los demás.",
  str_item_intro_7000401 = "Galletas que Connolly trajo para Dayna pero fueron robadas por guardias sirenos. Estas no tienen azúcar, según el pedido de Dayna.",
  str_item_intro_7000402 = "Borrador para la fortaleza del Señor Aqua. Probablemente no sea correcto, pero Queen Connolly se reserva todos los derechos de interpretación.",
  str_item_intro_7000403 = "Este nuevo instrumento musical que los habitantes del pueblo encontraron para Connolly puede emitir sonidos más fuertes y autoritarios para transmitir enojo.",
  str_item_intro_7000404 = "La Partitura Acuática que Connolly encontró en el viejo ático, ahora firmada con un nuevo nombre.",
  str_item_intro_7000405 = "Un retrato de Dayna pintado por un artista en una ciudad submarina, actualmente colocado en un asiento vacío por Queen Connolly como un accesorio durante el ensayo de su discurso.",
  str_item_intro_7000406 = "Un retrato de Robyn pintado por un artista en un pueblo submarino, actualmente colocado en un asiento vacío por Queen Connolly como un accesorio durante el ensayo de su discurso.",
  str_item_intro_7000407 = "Un retrato de un consultor misterioso pintado por un artista en un pueblo submarino, actualmente colocado en un asiento vacío por Queen Connolly como accesorio durante el ensayo de su discurso.",
  str_item_intro_7000408 = "Un retrato de un pez amigable pintado por un artista en un pueblo submarino, actualmente colocado en un asiento vacío por Queen Connolly como accesorio durante el ensayo de su discurso.",
  str_item_sub_intro_7000400 = "\"Ella duerme en el ático, comiendo lo que otros rechazaron. Hablando en susurros suaves, escondiéndose en los rincones más lejanos. Barriendo la habitación durante el día, tocando el instrumento por la noche. ¡Consolando su solitario corazón con música!\"",
  str_item_sub_intro_7000401 = "\"¡Mis galletas! ¡Connolly me las dio! ¿Por qué los sucios lacayos no perdonaron ni las galletas!\"",
  str_item_sub_intro_7000402 = "\"¡De otro mundo, los... estéticos geniales... disfrutar!\"",
  str_item_sub_intro_7000403 = "\"¡Dolor y tristeza... encontrarán salvación en la música!\"",
  str_item_sub_intro_7000404 = "\"Una vez expresó el deseo de que le diera un nuevo nombre. Reflexioné mucho tiempo. Rubinstein, Salieri, Leopold, Dvorak... Esos eran sus favoritos... ¿Qué, algo más íntimo?\"",
  str_item_sub_intro_7000405 = "\"¿Estaba siendo demasiado cáustico, dices? ¿Cómo no serlo cuando estaba defendiendo a mis hermanos?\"",
  str_item_sub_intro_7000406 = "\"Sí, un pez me llamó plano y apenas perceptible antes... Pero es exactamente así como sobrevivo...\"",
  str_item_sub_intro_7000407 = "\"¿Quieres que salga de mi retiro? Bueno, eso te va a costar.\"",
  str_item_sub_intro_7000408 = "\"¿Quién soy yo para Queen Connolly, preguntas? ¡Eso es confidencial!\"",
  str_item_7000801 = "Antiguo",
  str_item_intro_7000801 = "Se encuentran antigüedades en cada esquina de Twin Pavilions Bay. Los artefactos culturales de Longzhou son muy valorados en otros países, pero algunos se obtienen a través de transacciones honestas que involucran pedidos y pagos correspondientes, mientras que otros son robados en las sombras por ladrones.",
  str_item_6030101 = "Cuaderno de bocetos en miniatura",
  str_item_6030102 = "Sonrisa Temperatura",
  str_item_6030103 = "Eva Dawn",
  str_item_6030104 = "Templo de Lumopolis",
  str_item_6030105 = "Arte del Equilibrio",
  str_item_6030106 = "Oración Inocente",
  str_item_6030107 = "Señal Acuática",
  str_item_6030108 = "Solo de amor",
  str_item_6030109 = "Hogar maravilloso",
  str_item_6030110 = "Sueños de Glicinia",
  str_item_6030111 = "La Flor y la Espada Mágica",
  str_item_6030112 = "Barco de Sueños",
  str_item_6030113 = "Su mirada vigilante",
  str_item_6030114 = "Su Sagrado Juramento",
  str_item_6030115 = "Espada Regal",
  str_item_6030116 = "Dulce Locomotora",
  str_item_6030117 = "El Nuevo Look de Piedra de Caza",
  str_item_6030118 = "Bosque de Crema",
  str_item_6030119 = "Placa de identificación de Soldado",
  str_item_6030120 = "Luz de Estrella",
  str_item_6030121 = "Bandera Illumina",
  str_item_6030122 = "Pensamiento de Nikinis",
  str_item_6030123 = "Deseo de Nepolis",
  str_item_6030124 = "Espejo de Northland",
  str_item_intro_6030101 = "Medallón Stand By Me.\nEl pequeño cuaderno de dibujo muestra patrones infantiles, pero no puede ocultar los sentimientos de renuencia y apego en su interior, lo que hace difícil deshacerse de él.",
  str_item_intro_6030102 = "Medallón Stand By Me.\nIncluso si llega el día del juicio final, siempre preparará agua a la temperatura adecuada para su hermana menor.",
  str_item_intro_6030103 = "Medallón Stand By Me.\nEn aquellos años oscuros, esta flor fue su amanecer.",
  str_item_intro_6030104 = "Medallón Stand By Me.\nUn reconocimiento del Templo de Lumopolis.",
  str_item_intro_6030105 = "Medallón Stand By Me.\nLa mirada aguda de Irridon no perdona ninguna balanza desequilibrada.",
  str_item_intro_6030106 = "Medallón Stand By Me.\nEn aquel entonces, Paloma todavía estaba dispuesto a creer...",
  str_item_intro_6030107 = "Medallón Stand By Me.\n¡Esta es la apreciación del gran Señor Aqua! ¡Vosotros mortales, estirad vuestros miembros para recibir mi gracia!",
  str_item_intro_6030108 = "Medallón Stand By Me.\nJugué esto en solitario con la esperanza de mis familiares, el cuidado de mis compañeros, así como... amor y valentía.",
  str_item_intro_6030109 = "Medallón Stand By Me.\nSolo buscaba un refugio, pero para mi sorpresa, lo convertí en un hogar maravilloso.",
  str_item_intro_6030110 = "Medallón Stand By Me. \n¿Es este calor que siento ahora el resplandor del sol de la mañana o tu calor después de pasar por las espinas afiladas?",
  str_item_intro_6030111 = "Medallón Stand By Me. \nMuy pocas personas saben que la flor del árbol casto también florece. Sin embargo, es más pequeña que una flor de glicinia, es de un color lavanda tenue y se parece a la falda de un espadachín.",
  str_item_intro_6030112 = "Medallón Stand By Me.\nCuando ella pase por el parloteante Río Dorado un día, recordará el paseo en bote en sus sueños y esperará compartir un bote con cierta persona.",
  str_item_intro_6030113 = "Medallón Stand By Me.\n\"Tú eres la razón por la que el mundo vale la pena proteger.\"",
  str_item_intro_6030114 = "Medallón Stand By Me.\n\"Tú eres la razón por la que quiero proteger este mundo.\"",
  str_item_intro_6030115 = "Medallón Stand By Me. \nHa sido imbuido con una fuerza extraordinaria a través de la infusión del amor de Regal. Quizás esta sea la única razón por la que puede permanecer a su lado en una forma diferente.",
  str_item_intro_6030116 = "Un Medallón Stand By Me. \nCuando se va, parece una máquina fría e insensible. Solo cuando regresa se hace evidente su dulce naturaleza.",
  str_item_intro_6030117 = "Un medallón Stand By Me.\nDado que deshacerse de él es imposible... Podría servir como un accesorio de moda único.",
  str_item_intro_6030118 = "Un medallón Stand By Me. Árboles que fluyen con crema espesa y flores que dan los frutos más dulces... El lugar perfecto para un picnic, si alguna vez surge la oportunidad.",
  str_item_intro_6030119 = "Medallón Stand By Me.\nCada etiqueta representa una vida. May que todas estas almas resplandecientes descansen en paz.",
  str_item_intro_6030120 = "Medallón Stand By Me. \n¿Quiénes son los padres de esta persona? ¿Tiene esta persona hijos o hermanos? El nombre inscrito en piedra permanece en silencio mientras refleja el camino por delante.",
  str_item_intro_6030121 = "Medallón Stand By Me. \nLas banderas ondean al viento mientras suena el llamado a las armas. Los defensores más desinteresados de Astra avanzan sin miedo, nunca retroceden mientras mantienen a raya la oscuridad.",
  str_item_intro_6030122 = "Medallón Stand By Me.\n\"Todo lo que quiero es quedarme al lado de mi hermana...\"",
  str_item_intro_6030123 = "Medallón Stand By Me.\n\"Todo lo que deseo es que mi hermana pequeña sobreviva...\"",
  str_item_intro_6030124 = "Medallón Stand By Me. \nEste espejo ha presenciado la caída de demasiadas cosas. Quizás sea hora de que vea algo nuevo.",
  str_item_6130101 = "Losa conmemorativa Stand By Me",
  str_item_6130102 = "Placa de espejo Stand By Me",
  str_item_6130103 = "Tablero de concierto Stand By Me",
  str_item_6130104 = "Tablero de sueños Stand By Me",
  str_item_6130105 = "Junta de Miradas Compartidas",
  str_item_6130106 = "Tablero Stand By Me",
  str_item_6130107 = "Tablero militar Stand By Me",
  str_item_6130108 = "Tablero de poesía Stand By Me",
  str_item_intro_6130101 = "Tablero conmemorativo Stand By Me.\nSe acabó; el pasado se fue. Volvamos a casa.",
  str_item_intro_6130102 = "Tablero conmemorativo Stand By Me.\nEl que está en el espejo, despertemos juntos.",
  str_item_intro_6130103 = [[
Tablero conmemorativo Stand By Me.
Mi mente nunca ha sido tan fuerte y mi voz nunca ha sido tan melodiosa.]],
  str_item_intro_6130104 = "Tablero conmemorativo Stand By Me.\nElla lucha contra la maldición todos los días después de despertarse por la mañana, pero sus sueños son brillantes: dará la bienvenida a la tenue luz de la mañana en una ciudad ordenada y bulliciosa.",
  str_item_intro_6130105 = "Tablero conmemorativo Stand By Me.\nAunque mil años puedan haberse desvanecido como polvo, disipándose en la nada, mi corazón permanece firme.",
  str_item_intro_6130106 = "Un tablero conmemorativo Stand By Me.\n¡Clickety-clack, clickety-clack! Aferrándose a las vías, el tren atraviesa un sueño brillante. Pasa por el Bosque de Crema, por una fuente de miel, y por los arrepentimientos fermentados de un viajero solitario...",
  str_item_intro_6130107 = "Tablero conmemorativo Stand By Me.\n\"Estoy dispuesto a ser templado innumerables veces, porque creo firmemente que estas pruebas me llevarán a la luz de Illumina. La bala de metal completo afilada encapsula nuestras aspiraciones inquebrantables.\"",
  str_item_intro_6130108 = "Tablero conmemorativo Stand By Me.\n\"Su cuerpo está sepultado en la nieve, su alma está atada por el espejo y su rostro está coronado con flores marchitas, pero su amor nunca se marchita.\"",
  str_item_3001000 = "Fragmentos de sueños",
  str_item_intro_3001000 = "Fragmentos obtenidos de una historia donde la realidad y la ilusión se entrelazan, narrando rastros del mundo real. Se pueden intercambiar por recompensas de artículos en la tienda Paisajes Auténticos de Sueños.",
  str_item_get_3001000 = "Dream - Conversión de vencimiento de tokens de tienda temática",
  str_item_3001001 = "Metamorfosis",
  str_item_intro_3001001 = "Un recuerdo dejado atrás después de enfrentar desafíos y experimentar el crecimiento. Se puede canjear por recompensas de artículos en Dream - Awakening in the Storm - Memory Workshop.",
  str_item_get_3001001 = "Sueño - Despertar en la etapa Tormenta",
  str_item_3001002 = "Fragmento de sedimento",
  str_item_intro_3001002 = "Fragmentos obtenidos luego de enfrentar desafíos y experimentar crecimiento. Se pueden canjear por recompensas de artículos en Dream - Awakening in the Storm - Memory Workshop.",
  str_item_get_3001002 = "Sueño - Despertar en la etapa Tormenta",
  str_item_3001003 = "Ingenio",
  str_item_intro_3001003 = "El factor clave para que Eve permanezca racional y lúcida, permitiéndole enfrentarse al Omen en Awakening in the Storm. El punto de ingenio se repondrá en 3 puntos cada día a las 05:00 (UTC+0) o 00:00 (UTC-5) (No se otorgarán puntos si se alcanza el límite).",
  str_item_get_3001003 = "Recuperación automática con el tiempo",
  str_item_3001004 = "Ondas de alegría",
  str_item_intro_3001004 = "La taza favorita de Eve contiene solo agua común, pero le da fuerza. Recolecta y mejora el nivel \"Las sonrisas llevan a la felicidad\".",
  str_item_get_3001004 = "Obtener por etapas completas de Pesadilla en Sueño con 3-Estrellas por primera vez.",
  str_item_3001005 = "Contrapesos del Alma",
  str_item_intro_3001005 = "Un peso obtenido durante la búsqueda del verdadero yo para equilibrar las balanzas de la vida. Se puede utilizar para intercambiar recompensas de objetos en Sueño - Pruebas Entre Ondas Doradas - Subasta de Pruebas.",
  str_item_get_3001005 = "Sueño - Etapa de Pruebas Entre Ondas Doradas",
  str_item_3001006 = "Vela de Justicia",
  str_item_intro_3001006 = "Una llama de vela estrellada dejada atrás en el camino de buscar la justicia en el corazón de uno. Se puede utilizar para intercambiar recompensas de objetos en Sueño - Pruebas Entre Ondas Doradas - Subasta de Pruebas.",
  str_item_get_3001006 = "Sueño - Etapa de Pruebas Entre Ondas Doradas",
  str_item_3001007 = "Ingenio",
  str_item_intro_3001007 = "Como clave para ayudar a mantener la racionalidad y claridad, se consumirá durante la exploración pero puede reponerse gradualmente con el tiempo.",
  str_item_get_3001007 = "Recuperación automática con el tiempo",
  str_item_3001008 = "Luz de Justicia",
  str_item_intro_3001008 = "La luz de la justicia que Irridon ha recuperado a través de sus propios esfuerzos. Acumúlala para subir de nivel el Foco de la Verdad.",
  str_item_get_3001008 = "Obtener por etapas completas de Pesadilla en Sueño con 3-Estrellas por primera vez.",
  str_item_3001010 = "Concha de Eco",
  str_item_intro_3001010 = "Dentro de esta concha marina que resuena melodías, se encuentran fragmentos de partituras antiguas canjeables por premios en el Dream: Café de Burbujas Marinas Fantasía Subacuática de Connolly.",
  str_item_get_3001010 = "Sueño: Escenario de Fantasía Subacuática de Connolly",
  str_item_3001011 = "Deliciosa Fluorófora",
  str_item_intro_3001011 = "Las algas brillantes en la esquina del fondo del océano solían utilizarse para hacer una bebida muy popular en las profundidades marinas. Canjeable por premios en el Dream: Café de Burbujas Marinas Fantasía Subacuática de Connolly.",
  str_item_get_3001011 = "Sueño: Escenario de Fantasía Subacuática de Connolly",
  str_item_3001012 = "Ingenio",
  str_item_intro_3001012 = "Como clave para ayudar a mantener la racionalidad y claridad, se consumirá durante la exploración pero puede reponerse gradualmente con el tiempo.",
  str_item_get_3001012 = "Sueño: Escenario de Fantasía Subacuática de Connolly",
  str_item_3001013 = "Estudio del Pact",
  str_item_intro_3001013 = "El intento de Connolly de comprender todo lo descrito por el Señor del Agua y dar sentido a la profunda sabiduría. Acumula para mejorar el nivel de Conexión Aqua.",
  str_item_get_3001013 = "Obtener por etapas completas de Pesadilla en Sueño con 3-Estrellas por primera vez.",
  str_item_3001014 = "Horquilla de Glicinia",
  str_item_intro_3001014 = "Un pasador hecho de pequeñas flores resistentes que se puede usar para canjear recompensas de artículos en Sueño - Canción de Espada Bajo un Dosel de Sueños - Intercambio Verde.",
  str_item_get_3001014 = "Sueño - Canción de la Espada Bajo un Dosel de Sueños Escenarios",
  str_item_3001015 = "Moneda antigua de cobre",
  str_item_intro_3001015 = "Una moneda antigua oxidada del Este que ya no se usa como forma de moneda con el tiempo. Se puede usar para canjear recompensas de artículos en Sword Song Under a Canopy of Dreams - Verdant Exchange.",
  str_item_get_3001015 = "Sueño - Canción de la Espada bajo un dosel de Sueños Escenarios",
  str_item_3001016 = "Ingenio",
  str_item_intro_3001016 = "Como clave para ayudar a mantener la racionalidad y claridad, se consumirá durante la exploración pero puede reponerse gradualmente con el tiempo.",
  str_item_get_3001016 = "Sueño - Canción de la espada bajo un dosel de sueños Escenarios",
  str_item_3001017 = "Voluntad de Forjar Espada",
  str_item_intro_3001017 = "Cada batalla es una oportunidad para mejorar el manejo de la espada de un espadachín. La mejora constante llevará a un cambio cualitativo. Acumula para mejorar el nivel de Corazón de Espada.",
  str_item_get_3001017 = "Obtener por etapas completas de Pesadilla en Sueño con 3-Estrellas por primera vez.",
  str_item_3001018 = "Capital de Trabajo",
  str_item_intro_3001018 = "Como diría la gente de Umbraton, el Gremio Índigo comenzó como un simple gremio de fachada, pero no es el estilo de su fundador decir que no al dinero, así que ¿por qué no operarlo como un gremio adecuado?",
  str_item_3001019 = "Energía Auspiciosa",
  str_item_intro_3001019 = "La Energía Auspiciosa obtenida de las transacciones comerciales monetarias y financieras puede usarse para mejorar el Feng Shui y eliminar el mal.",
  str_item_3001021 = "Corona de Plata",
  str_item_intro_3001021 = "La corona de ramas de olivo simboliza la victoria y la paz. Canjeable por premios en Sueño - Vigilia de Mil Años - Mercado Northwind.",
  str_item_get_3001021 = "Sueño - Una Vigilia de Mil Años",
  str_item_3001022 = "Moneda del vigilante",
  str_item_intro_3001022 = "Moneda de bronce creada para conmemorar el triunfo de la Legión NORTHWIND. Canjeable por premios en Sueño - Vigilia de Mil Años - Mercado NORTHWIND.",
  str_item_get_3001022 = "Sueño - Una Vigilia de Mil Años",
  str_item_3001023 = "Ingenio",
  str_item_intro_3001023 = "Como clave para ayudar a mantener la racionalidad y claridad, se consumirá durante la exploración pero puede reponerse gradualmente con el tiempo.",
  str_item_get_3001023 = "Recuperación automática con el tiempo",
  str_item_3001024 = "Espiga de Trigo Fragante",
  str_item_intro_3001024 = "La reconfortante fragancia del trigo, simbolizando promesas para un futuro brillante, es un recordatorio constante para el alma dentro de la espada, no te vayas aún. Acumula para subir de nivel el Alma de la Espada.",
  str_item_3001025 = "Fragmento de templo",
  str_item_intro_3001025 = "Con un estruendoso choque, un lado del templo se derrumba, convirtiendo las piedras intrincadamente talladas y los valiosos vasos ofrecidos en su interior en fragmentos dispersos. Sin embargo, estos fragmentos aún conservan cierto valor.",
  str_item_3001026 = "Caramelo Pop Rocks",
  str_item_intro_3001026 = "Un caramelo extraño hecho de una planta rara. Se puede usar para intercambiar por recompensas en Sueño - Paraíso de la Comida Rara y Extravagante - Entrega de Delicias.",
  str_item_get_3001026 = "Sueño - Etapa del Paraíso Comida Rara y Estrafalaria",
  str_item_3001027 = "Madera Crema",
  str_item_intro_3001027 = "Un tipo especial de madera recolectada de los árboles del Bosque de Crema. Se puede usar para intercambiar por recompensas en Sueño - Paraíso de la Comida Rara y Divertida - Entrega de Delicias.",
  str_item_get_3001027 = "Sueño - Etapa del Paraíso Comida Rara y Estrafalaria",
  str_item_3001028 = "Ingenio",
  str_item_intro_3001028 = "Como clave para ayudar a mantener la racionalidad y claridad, se consumirá durante la exploración pero puede reponerse gradualmente con el tiempo.",
  str_item_get_3001028 = "Recuperación automática con el tiempo",
  str_item_3001029 = "Corazón apreciado",
  str_item_intro_3001029 = "Un producto de la preocupación y el llamado sin tapujos de Pact... Aunque la Piedra de Caza nunca lo pidió. Reúne más para aumentar el nivel de la Piedra de Caza.",
  str_item_3001030 = "Vajilla fina",
  str_item_intro_3001030 = "Una exquisita obra de arte creada por un maestro. Se puede utilizar para hacer un plato de alta calidad aún más atractivo.",
  str_item_3001031 = "Insignia de Phospherus",
  str_item_intro_3001031 = "Una antigua insignia de Illumina, un artículo de colección de profunda significación. La medalla en sí no es valiosa, pero se ha convertido en un tesoro inestimable debido a la gloria del héroe que la ganó. Otorgar tal medalla a un héroe es solo una pequeña muestra de gratitud. Se puede canjear por recompensas de artículos en Sueño - Noche Evanescing bajo la luz de las estrellas - Distribución de Sueños.",
  str_item_get_3001031 = "Sueño: Noche Evanescente a Luz de Estrella",
  str_item_3001032 = "Vale de Illumina",
  str_item_intro_3001032 = "Vales populares en Illumina. Se ganan puntos dependiendo de la duración del trabajo y el servicio, que se pueden usar para canjear varios recursos. Se pueden canjear por recompensas de artículos en Sueño - Noche Evanescente a la Luz de las Estrellas - Distribución de Sueños.",
  str_item_get_3001032 = "Sueño: Noche Evanescente a Luz de Estrella",
  str_item_3001033 = "Ingenio",
  str_item_intro_3001033 = "Como clave para ayudar a mantener la racionalidad y claridad, se consumirá durante la exploración pero puede reponerse gradualmente con el tiempo.",
  str_item_get_3001033 = "Recuperación automática con el tiempo",
  str_item_3001034 = "Silbato",
  str_item_intro_3001034 = "Los soldados están tan acostumbrados al agudo chillido del silbato que en realidad no pueden sentirse seguros sin él. Recoge suficiente para aumentar el nivel de la Ronda Afilada.",
  str_item_3001035 = "Juegos de guerra",
  str_item_intro_3001035 = "Una forma rara de entretenimiento en Illumina, conservando los elementos de combate. Este exquisito juego de guerra transmite el corazón de su creador.",
  str_item_3001036 = "Marcador de Flor Seca",
  str_item_intro_3001036 = "Un marcador hecho por ella misma que la chica usaba mientras leía. Acompañada de flores, hojeó innumerables libros de fábulas, buscando rastros de su pasado fragmentado. Se puede usar para intercambiar por recompensas en Sueño - A través del espejo Soneto de invierno - Mercado sin nombre.",
  str_item_get_3001036 = "Sueño - A través del espejo de invierno Sonnet Escenarios",
  str_item_3001037 = "Fragmento de espejo",
  str_item_intro_3001037 = "Estos fragmentos son extensiones de la fuerza del espejo mágico, y dentro de ellos yace la esencia de la estructura del mundo del espejo. Cada pieza forma un pequeño dominio fracturado. Se pueden usar para intercambiar por recompensas en Sueño - A través del espejo Soneto de invierno - Mercado sin nombre.",
  str_item_get_3001037 = "Sueño - A través del espejo de invierno Sonnet Escenarios",
  str_item_3001038 = "Ingenio",
  str_item_intro_3001038 = "Como clave para ayudar a mantener la racionalidad y claridad, se consumirá durante la exploración pero puede reponerse gradualmente con el tiempo.",
  str_item_get_3001038 = "Recuperación automática con el tiempo",
  str_item_3001039 = "Dimensión Espejo Florecer",
  str_item_intro_3001039 = "El poder de Nikinis a menudo se manifiesta en forma de flores, y la Dimensión Espejo no es una excepción.",
  str_item_3001040 = "Colección de Fábulas de Northland",
  str_item_intro_3001040 = "Nikinis está buscando sus recuerdos perdidos, y aunque busca ayuda de los demás, nunca renuncia a las pistas dentro de sí misma.",
  str_item_not_enough_plm = "Frutas de espino de fuego insuficientes",
  str_item_3751396 = "Ojeras detrás de las gafas de sol",
  str_item_3751397 = "Dama de la Iglesia en Crepúsculo",
  str_item_3751551 = "Pesares del nuevo Gran Mariscal",
  str_item_intro_3751396 = "Que la luz brille sobre Crepúsculo, disipando las sombras que allí permanecen.",
  str_item_intro_3751397 = "¿Ojeras? Para nada.",
  str_item_intro_3751551 = "¿No podemos tener una conversación que no involucre informes de trabajo?",
  str_item_3000131 = "Llamarada de estrella especial Sinfonía del Crepúsculo",
  str_item_intro_3000131 = "Se puede usar para reclutar una vez del evento de reclutamiento exclusivo de Twilight Symphony.\nEste artículo caducará eventualmente y no se convertirá en otro elemento; por favor recuerde usarlo antes de que finalice el evento de reclutamiento exclusivo de Twilight Symphony.",
  str_item_10000992 = "Kleken Caja Unida",
  str_item_intro_10000992 = "Permite que Kleken se una a tu aventura.",
  str_item_1000099 = "Kleken Caja Unida",
  str_item_intro_1000099 = "Permite que Kleken se una a tu aventura.",
  str_item_3755023 = "Adorable Perrito Títere",
  str_item_3755024 = "¿Rana?",
  str_item_3755025 = "Dawn Flor",
  str_item_intro_3755023 = "Desbloquea el avatar correspondiente.\n*gemidos*... ¿Te gusta?",
  str_item_intro_3755024 = "Desbloquea el avatar correspondiente.\n¿Diente de león? ¡No huyas de mí!",
  str_item_intro_3755025 = "Desbloquea el marco de avatar correspondiente.\nPequeña como es la flor blanca, representa el amanecer...",
  str_item_3661219 = "Retrato del Caballero Fiat",
  str_item_intro_3661219 = "Artículo de muebles. Se puede colocar en las habitaciones de tu Colossus.\nUn retrato creado a imagen de Irridon durante sus días como caballero, aparentemente un regalo que una joven no pudo entregar.\n\"Lady Irridon, te agradezco sinceramente por tu ayuda y cuidado continuos. Espero que sigas abrazando los valores de justicia y compasión, guiando a Lumopolis hacia un futuro más brillante.\"",
  str_item_3661220 = "Retrato de Monja Inocente",
  str_item_intro_3661220 = "Artículo de muebles. Se puede colocar en las habitaciones de su Colossus.\nUn retrato creado a imagen de Paloma durante sus días como monja, aparentemente un regalo que un padre no pudo dar.\n\"Pam, que siempre te mantengas inocente y amable, y que nuestra familia siempre encuentre la felicidad.\"",
  str_item_3751039 = "Determinación Inquebrantable",
  str_item_3751040 = "fin de la luz",
  str_item_3751041 = "Himno Triunfal",
  str_item_3751398 = "Sed de Conocimiento",
  str_item_3751399 = "Poder del Guardián",
  str_item_3751400 = "¿Qué dijiste?",
  str_item_intro_3751039 = [[
Desbloquea el avatar correspondiente.
"Negador, Reinhardt... Pase lo que pase, que cada uno encuentre su propio camino."]],
  str_item_intro_3751040 = "Desbloquea el avatar correspondiente.\n\"No tengo intención ni interés en hacer enemigos; simplemente son obstáculos en mi camino.\"",
  str_item_intro_3751041 = "Desbloquea el avatar correspondiente.\n\"El Iluminado puede ser cualquiera: tú, yo, quien sea, siempre y cuando guíe a los Aurorians a través de los desafíos.\"",
  str_item_intro_3751398 = [[
Desbloquea el avatar correspondiente.
"Oh, el cielo nocturno... es como una biblioteca infinita, que guarda todos los secretos del mundo."]],
  str_item_intro_3751399 = "Desbloquea el avatar correspondiente.\n\"Quizás algún día, pueda manejar con destreza este poder que el destino me ha otorgado.\"",
  str_item_intro_3751400 = "Desbloquea el avatar correspondiente.\n\"¿Eh?\"",
  str_item_3751552 = "Tema tabú",
  str_item_intro_3751552 = "Desbloquea el avatar correspondiente.\n\"¡Basta de esa broma del helado!\"",
  str_item_3751553 = "Alegre Tweety",
  str_item_intro_3751553 = "Desbloquea el avatar correspondiente.\n\"Con las vacaciones acercándose, ya tengo mis planes de vacaciones listos. ¿Quieres saber cuál es el plan de Tweety?\"",
  str_item_3763034 = "Dulce sorpresa",
  str_item_intro_3763034 = "Desbloquea el marco de avatar correspondiente.\nZarya estaba preocupada de que el frío intenso de Northland pudiera ser demasiado para ti, así que te regaló su sombrero.",
  str_item_3661215 = "Escritorio para escribir",
  str_item_intro_3661215 = "Artículo de muebles. Se puede colocar en las habitaciones de su Colossus.\nUn elegante escritorio de madera que brinda tranquilidad en el trabajo.",
  str_item_3661216 = "Mesa de café pequeña",
  str_item_intro_3661216 = "Artículo de muebles. Se puede colocar en las habitaciones de su Colossus.\nUna pequeña mesa de café de madera. Una sección de la superficie está hecha de mármol, lo que le da un aire de refinamiento.",
  str_item_3661217 = "Mesa lateral de búho",
  str_item_intro_3661217 = "Artículo de muebles. Se puede colocar en las habitaciones de su Colossus.\nUn búho se posa sobre esta pequeña mesa como si estuviera mirando hacia la distancia.",
  str_item_3661218 = "Escoba mágica",
  str_item_intro_3661218 = "Artículo de muebles. Se puede colocar en las habitaciones de su Colossus.\nAlgunas leyendas dicen que si te sientas en él, volará alto en el aire. ¿De dónde podría haber surgido tal idea?",
  str_item_5234055 = "Adorno de barco",
  str_item_intro_5234055 = "Un pequeño y colorido barco, colocado en posición vertical y utilizado como decoración. ¿Puede la simple vista de él realmente inspirar el deseo de zarpar hacia tierras lejanas?",
  str_item_3661052 = "Luciérnaga Efímera",
  str_item_intro_3661052 = "Artículo de muebles. Se puede colocar en las habitaciones de su Colossus.\nSolo puede flotar en el aire y es completamente incapaz de moverse... Entonces, ¿para qué sirve? ¿Para colgar cosas? ¿Pasamanos?",
  str_item_3000338 = "Resto antiguo",
  str_item_intro_3000338 = "Fragmentos de alguna reliquia antigua dispersos por la tierra a lo largo de innumerables años. Si alguien estuviera dispuesto a reconocer su valor, también podría estar dispuesto a pagar una cierta cantidad de remuneración para adquirirlos.",
  str_item_3751401 = "El baloncesto de Brock",
  str_item_3751402 = "Vice Rookie Tenis Meja",
  str_item_3751403 = "Esports Pro Gronru",
  str_item_3751404 = "Tuan Penembak Jitu Charon",
  str_item_intro_3751401 = "Desbloquea el avatar correspondiente. ¡Mira mi bandeja de tres pasos! ¡Yargh! ¿Por qué tuvo que rebotar directamente en el tablero?",
  str_item_intro_3751402 = "Desbloquea el avatar correspondiente. ¡El deporte es vida! ¡Incluso si soy un novato, daré todo lo que tengo en la mesa de ping pong!",
  str_item_intro_3751403 = "Desbloquea el avatar correspondiente. Cuando se trata de juegos, ¡nunca me dejaré quedar atrás! ¡Mírame dominar a esos novatos en la próxima gran competición de deportes electrónicos!",
  str_item_intro_3751404 = "Desbloquea el avatar correspondiente. ¿No lo sabías? ¡Siempre me desempeño magníficamente en el campo de tiro!",
  str_item_3440011 = "Ataúd de Luz",
  str_item_intro_3440011 = "Abre para obtener uno de los siguientes al azar: Nightium ×10,000, Nightium ×5,000, General Jasper II ×2, General Jasper I ×3, Sublime ×100 o Sublime ×50.",
  str_item_3440012 = "Caja de Iluminación",
  str_item_intro_3440012 = "Abre para obtener uno de los siguientes al azar: Nightium ×5,000, Nightium ×2,000, Nightium ×1,000, General Jasper II ×1, General Jasper I ×2 o Sublime ×30.",
  str_item_3440013 = "Ataúd del Mar",
  str_item_intro_3440013 = "Abre para obtener uno de los siguientes al azar: Anonymous Gift II ×1, Coalition Order Box III ×2, Nightium ×20,000 o General Jasper II ×4.",
  str_item_3440019 = "Ataúd del Mar",
  str_item_intro_3440019 = "Abre para obtener uno de los siguientes al azar: Anonymous Gift II ×1, Coalition Order Box III ×2, Nightium ×20,000 o General Jasper II ×4.",
  str_item_3755036 = "Caballero de Justicia Irridon",
  str_item_intro_3755036 = "Desbloquea el avatar correspondiente.\n\"¡No dejaré que se me escapen pistas!\"",
  str_item_3755037 = "La cocina de Pam.",
  str_item_intro_3755037 = "Desbloquea el avatar correspondiente.\n\"Puede que no se vea elegante, pero créeme, ¡sabe fantástico!\"",
  str_item_6110001 = "Tablero de arte Stand By Me",
  str_item_intro_6110001 = "Tablero conmemorativo Stand By Me.\nEl patrón en el tablero evoca imágenes de visitantes distantes traídos aquí por la brisa del mar, acompañados por la suave melodía del pipa y el ondear de las banderas...",
  str_item_3661221 = "Modelo de tren souvenir",
  str_item_intro_3661221 = "Un regalo para el público del estreno de la película de Charon. Esta magnífica mini locomotora, junto con la impresionante actuación del famoso actor, dejó una gran impresión en los espectadores.\n\"¡Recuerda esta sensación!\"",
  str_item_3000027 = "Cupón de Corazón",
  str_item_3000028 = "Globo de corazón",
  str_item_intro_3000027 = "Úsalo para votar por el Aurorian que te gusta en el Evento de Votación de Atuendos.\n\"¿Sentirán mi afecto por ellos?\"",
  str_item_intro_3000028 = "Úsalo para votar por el atuendo que te gusta en el evento de votación de atuendos.\n\"Por favor, entrégalo con cuidado al destinatario, o tu amor podría desvanecerse en el cielo.\"",
  str_item_3661222 = "Retrato de la Chica Clarinetista",
  str_item_3661223 = "Retrato Queen Acuático",
  str_item_intro_3661222 = "Artículo de muebles. Se puede colocar en las habitaciones de su Colossus.\nEste artículo fue originalmente producido como una tetera especial para cafeterías, pero no recibió buenas críticas debido a su diseño de descarga de agua por la boca.\n\"¡N-No uses mi apariencia para algo así!\"",
  str_item_intro_3661223 = "Artículo de muebles. Se puede colocar en las habitaciones de su Colossus.\nUn fino retrato de la reina, ahuecado para reducir su peso. Alguien sugirió que el diseño podría usarse para desarrollar un contenedor para jugo de Fluorophora, pero la reina lo rechazó rotundamente.\n\"Ugh, ¿por qué... siempre me pasa esto a mí...?\"",
  str_item_3661224 = "Casillero Médico",
  str_item_3661225 = "Cama de enfermo",
  str_item_3661226 = "Carrito",
  str_item_3661227 = "Fila de Asientos",
  str_item_intro_3661224 = "Artículo de muebles. Se puede colocar en las habitaciones de su Colossus.\nUn casillero de madera con varias botellas y frascos en él. Esperemos que estos sueros puedan aliviar el sufrimiento de los demás.",
  str_item_intro_3661225 = "Artículo de muebles. Se puede colocar en las habitaciones de su Colossus.\nUna cama hecha especialmente para pacientes. Ven aquí a descansar si te sientes mal.",
  str_item_intro_3661226 = "Artículo de muebles. Se puede colocar en las habitaciones de su Colossus.\nUn carrito médico simple. Es extremadamente importante aunque tenga espacio limitado.",
  str_item_intro_3661227 = "Artículo de muebles. Se puede colocar en las habitaciones de su Colossus.\nUna fila de asientos. Tal vez puedas aliviar tu ansiedad charlando con los compañeros que se sientan a tu alrededor.",
  str_item_5234056 = "Patio Tranquilo",
  str_item_intro_5234056 = "Un lugar maravilloso para refrescarse y descansar. Puedes venir aquí si te sientes preocupado por algo.",
  str_item_3000344 = "Jarra de colección",
  str_item_intro_3000344 = "¿Cuánto más necesito recolectar antes de poder parar...?",
  str_item_3000345 = "Cupón Divertido",
  str_item_intro_3000345 = "Estos cupones de sorteo de aspecto ordinario, hechos por el Gremio Umbraton, son la moneda designada para el juego de la Caja Sorpresa a Ciegas.",
  str_item_3661228 = "Cangrejo forjado en horno",
  str_item_3661229 = "Modelo de Barco de la Fortuna",
  str_item_intro_3661228 = "Artículo de muebles. Se puede colocar en las habitaciones de su Colossus.\nOriginalmente creado por Xuan Ji para ayudar a los artesanos en la forja mecánica, este autómata de Longzhou ha perdido su movilidad después de años de uso. Sin embargo, sigue siendo una pieza decorativa distintiva.",
  str_item_intro_3661229 = "Artículo de muebles. Se puede colocar en las habitaciones de su Colossus.\nEn los barcos de la fortuna que la gente de Longzhou envía al mar, se impregnan numerosos deseos. Por ejemplo, las monedas de cobre y los espejos incrustados en las juntas crean la disposición de las Siete Estrellas siguiendo la Luna, lo que significa buena fortuna y un viaje próspero. Aunque este es solo un modelo creado por Xuan Ji, no escatima en los detalles necesarios y los deseos sinceros.",
  str_item_3763035 = "Elixir curativo",
  str_item_intro_3763035 = "Desbloquea el marco de avatar correspondiente.\n\"No te preocupes, no te hará daño...\"",
  str_item_3751554 = "Debilitado",
  str_item_intro_3751554 = [[
Desbloquea el avatar correspondiente.
"Tos, tos... E-Estoy bien... solo necesito un poco de descanso."]],
  str_item_3751555 = "Corazón de gratitud",
  str_item_intro_3751555 = "Desbloquea el avatar correspondiente.\n\"¡Hoy invito yo!\"",
  str_item_3751405 = "Curador Cariñoso",
  str_item_intro_3751405 = "Desbloquea el avatar correspondiente.\n\"Por favor, siéntate y déjame echarle un vistazo.\"",
  str_item_3751406 = "La fuerza prevalece",
  str_item_intro_3751406 = "Desbloquea el avatar correspondiente.\n\"¡Perseguiré a cualquiera que se atreva a deberte dinero y no pagar!\"",
  str_item_3751407 = "Reliquia de mar profundo",
  str_item_intro_3751407 = "Desbloquea el avatar correspondiente.\nUn tesoro enterrado en lo profundo del océano.\nResiste el desgaste constante y la erosión del agua de mar, con la esperanza de algún día volver a la superficie en tierra.",
  str_item_3751408 = "Invitación de Xuan Ji",
  str_item_intro_3751408 = "Desbloquea el avatar correspondiente.\n\"Los Celestitas tienen algunas creencias similares a las de mi propio pueblo. ¿Te interesaría visitar Ye para un intercambio cultural?\"",
  str_item_3751556 = "Mecanismo de Forjacobre",
  str_item_intro_3751556 = "Desbloquea el avatar correspondiente.\n\"Una creación de maquinaria sin función práctica. Si lo encuentras estéticamente agradable, entonces vale la pena tenerlo.\"",
  str_item_3751409 = "Lluvia de Oro",
  str_item_intro_3751409 = "Desbloquea el avatar correspondiente.\n\"Aunque esto no es ni el 1% de mi riqueza, no hay razón para rechazar dinero gratis.\"",
  str_item_3751410 = "La Rotura del Señor Sombrío",
  str_item_intro_3751410 = "Desbloquea el avatar correspondiente.\n\"Ya casi son las vacaciones. Debería relajarme un poco.\"",
  str_item_3751557 = "Mate",
  str_item_intro_3751557 = [[
Desbloquea el avatar correspondiente.
"No dudes. Sorprende a tus enemigos y gana."]],
  str_item_3751558 = "Moneda afortunada",
  str_item_intro_3751558 = "Desbloquea el avatar correspondiente.\n\"Esta moneda de la suerte es para ti, que estás garantizado de ser bendecido con suerte en el próximo año.\"",
  str_item_3763036 = "Serpiente de Niebla",
  str_item_intro_3763036 = "Desbloquea el marco de avatar correspondiente.\nEsta serpiente de humo enroscada eventualmente devorará todo.",
  str_item_3751411 = "Ven a Tomar Té",
  str_item_intro_3751411 = "Desbloquea el avatar correspondiente.\n\"Son las tres en punto. ¿Quieres una taza de té?\"",
  str_item_3751559 = "Cerezo en flor",
  str_item_intro_3751559 = "Desbloquea el avatar correspondiente.\n\"Un color extraño se proyecta en la cara de Hiiro, probablemente por el color de las flores de cerezo que han florecido temprano en un lugar distante.\"",
  str_item_3751560 = "Croqueta Geek",
  str_item_intro_3751560 = "Desbloquea el avatar correspondiente.\n\"La sabiduría me sacia, no la comida.\"",
  str_item_3751412 = "Comandante Sabio",
  str_item_intro_3751412 = [[
Desbloquea el avatar correspondiente.
"Los Aurorianos son su propio enemigo."]],
  str_item_3763037 = "Regalo de Sakura",
  str_item_intro_3763037 = "Desbloquea el marco de avatar correspondiente.\nLa línea de sangre de la familia Sakura ha estado guardando silenciosamente Hiiro en nombre del resto del clan.",
  str_item_3751561 = "Masaje de Tigre",
  str_item_3751562 = "No Picante",
  str_item_3751563 = "Suave",
  str_item_3751564 = "Moderado",
  str_item_3751565 = "Astra Picante",
  str_item_intro_3751561 = "Desbloquea el avatar correspondiente.\n\"¿Quién puede resistirse a la tentación de frotar su cabeza contra un tigrito tan lindo con poderes tan deliciosos?\"",
  str_item_intro_3751562 = [[
Desbloquea el avatar correspondiente.
"Este nivel de picante no es nada para Rediesel Wrench."]],
  str_item_intro_3751563 = [[
Desbloquea el avatar correspondiente.
"La gente de Ye es aficionada a los platos picantes. Aunque el ultra picante es un poco demasiado para Dantang, ella es una excelente cocinera y puede entender la belleza de este sabor."]],
  str_item_intro_3751564 = "Desbloquea el avatar correspondiente.\n\"¡Siempre debes comer de manera elegante! Carleen se sigue recordando que no puede olvidar el protocolo de cena de los Caballeros Lumo solo por la estimulación en su boca.\"",
  str_item_intro_3751565 = "Desbloquea el avatar correspondiente.\n\"¡Ahhhhhhhhh! ¡Astra picante! Eso es lo primero que dijo el estornino después de comer la salsa de chile.\"",
  str_item_9997004 = "Vendaje de primeros auxilios",
  str_item_9997005 = "Escudo de Silvermoon",
  str_item_9997008 = "Diosa de la Misericordia",
  str_item_9997009 = "Piedra de maleficio",
  str_item_9997010 = "Nota de Desaparición",
  str_item_9997011 = "Armadura de berserker",
  str_item_9997012 = "Gloria Sol",
  str_item_9997013 = "Golpeador de trueno",
  str_item_9997014 = "Kaleidogema",
  str_item_9997015 = "espada de luz",
  str_item_9997016 = "Machete Silvermoon",
  str_item_9997017 = "Arco de Silvermoon",
  str_item_9997018 = "Cuchilla aguda",
  str_item_9997019 = "Gafas de Día",
  str_item_9997020 = "Pintura absorbente",
  str_item_9997021 = "Caída de Sakura",
  str_item_9997023 = "Máscara de DeathTouch",
  str_item_9997024 = "Mano de Dios",
  str_item_9997025 = "Muerte silenciosa",
  str_item_9997026 = "Cinturón de energía",
  str_item_9997027 = "Escudo de Lumina",
  str_item_9997028 = "Deslumbramiento de Segador",
  str_item_9997029 = "Amuleto de combo",
  str_item_9997030 = "Estatua de bonos",
  str_item_9997031 = "Colgante potencial",
  str_item_9997033 = "Energizador móvil",
  str_item_9997035 = "Segador de Almas",
  str_item_9997003 = "Vela curativa",
  str_item_9997006 = "Corazón de piedad",
  str_item_9997007 = "Escudo de sol",
  str_item_9997032 = "Insignia de resonancia",
  str_item_9997022 = "Bolsa de dormir",
  str_item_9997036 = "Manuscrito antiguo",
  str_item_9997037 = "Pestilencia",
  str_item_9997038 = "Chaos Blade",
  str_item_9997034 = "Botas de rotura",
  str_item_9997039 = "Moneda afortunada",
  str_item_9997040 = "Ecos dobles",
  str_item_9997041 = "Congelador flotante",
  str_item_9997042 = "Quemador flotante",
  str_item_9997043 = "Ira del Bosque Flotante",
  str_item_9997044 = "Trueno flotante",
  str_item_9997045 = "Plato del Alba",
  str_item_9997046 = "Aturdimiento de cristal",
  str_item_9997047 = "Caja mágica de Lumina",
  str_item_intro_9997004 = "Recarga un vendaje en el campo cuando comienza una batalla.",
  str_item_intro_9997005 = "Otorga un escudo del 20% del HP máximo que dura 2 rondas al comienzo de la batalla.",
  str_item_intro_9997008 = "Restaura HP al 30% al inicio de la batalla si el HP actual es inferior al 30%.",
  str_item_intro_9997009 = "Pierde el 7% de HP actual al comienzo de cada ronda. Después, inflige daño equivalente al 150% del ATK promedio del equipo a los enemigos dentro de 2 cúmulos circundantes.",
  str_item_intro_9997010 = "Aumenta el daño de la Habilidad Activa de los Aurorianos en un 50%. Pierden el 8% de su HP actual cada vez que se lanza una Habilidad Activa.",
  str_item_intro_9997011 = "Aumenta el daño de Chain Combo hasta en un 40% según el porcentaje de HP perdido por los aliados.",
  str_item_intro_9997012 = "Aumenta el daño de Aurorian en un 20% cuando el HP actual es superior al 70%.",
  str_item_intro_9997013 = "Al atacar a 3 o más enemigos al mismo tiempo, lanza un rayo que ataca a todos los enemigos, infligiendo daño igual al 100% del ATK promedio del equipo.",
  str_item_intro_9997014 = "Genera 1 mosaico cromático al azar en el campo al comienzo de cada ronda.",
  str_item_intro_9997015 = "Al eliminar al menos 15 fichas de una vez con un toque, aumenta el daño de Chain Combo de los aurorianos en un 30%. El Chain Combo no se puede lanzar si se eliminan menos de 8 fichas a la vez.",
  str_item_intro_9997016 = "Cuanto más cerca estén de un enemigo, mayor será el daño del Combo en Cadena de los Aurorianos, aumentándolo hasta un 20%.",
  str_item_intro_9997017 = "Cuanto más lejos estén de un enemigo, mayor será el daño del Combo en Cadena de los Aurorianos, aumentándolo hasta en un 30%.",
  str_item_intro_9997018 = "Los Aurorians Detonadores tienen un 30% de probabilidad de lanzar el Combo en Cadena 1 vez adicional.",
  str_item_intro_9997019 = "Aumenta en 1 el número de objetivos del Combo en Cadena de los Aurorianos Francotiradores.",
  str_item_intro_9997020 = "Supporter Aurorians +25% regeneration effects from Chain Combos and Active Skills in battle.",
  str_item_intro_9997021 = "Al comienzo de la batalla, reduce en 1 el tiempo de reutilización de la Habilidad Activa de los Aurorians Convertidores.",
  str_item_intro_9997023 = "Cuando las Habilidades Activas o Habilidades de Combo en Cadena lanzadas por los Aurorians infligen daño, hay un 30% de probabilidad de resolver de inmediato los efectos de Envenenamiento/Ardor/Sangrado del objetivo una vez.",
  str_item_intro_9997024 = "Todo el daño recibido por enemigos que están debilitados o bajo efectos de debilitados aumenta en un 20%.",
  str_item_intro_9997025 = "Derrota enemigos con menos del 7% de HP.",
  str_item_intro_9997026 = "Después de tocar para eliminar fichas, si los Aurorians no han lanzado el Chain Combo en esta ronda, reduce el tiempo de reutilización de la Habilidad Activa de todos los Aurorians en 1.",
  str_item_intro_9997027 = "Convierte un porcentaje del exceso de curación de los aurorianos en una pila de escudo que dura 1 ronda.",
  str_item_intro_9997028 = "Cuando se derrota a un enemigo Envenenado/Ardiente/Sangrante, inflige a otro enemigo aleatorio en el campo de batalla 1 acumulación de Envenenado.",
  str_item_intro_9997029 = "Reduce en 5 el número de casillas que deben eliminarse para activar la habilidad de apoyo de la facción.",
  str_item_intro_9997030 = "Cuando un auroriano lanza una Habilidad Activa, reduce en 1 el tiempo de reutilización de las Habilidades Activas de los aurorianos que tienen un vínculo con ellos.",
  str_item_intro_9997031 = "Reduce el tiempo de reutilización de la primera Habilidad Activa lanzada en la batalla en 2.",
  str_item_intro_9997033 = "Un indicador aparece aleatoriamente en el campo de batalla al comienzo de cada ronda. Después de destruir este indicador, el daño de Chain Combo aumenta en un 25% en esta ronda.",
  str_item_intro_9997035 = "Los aurorianos obtienen un 2% de Drenaje de Vida al infligir daño y pierden el 15% de su HP actual al comienzo de cada ronda.",
  str_item_intro_9997003 = "Restaura el 10% de Max HP después de ganar una batalla.",
  str_item_intro_9997006 = "Aumenta el HP máx. de todos los Aurorianos en un 3% después de ganar una batalla.",
  str_item_intro_9997007 = "Aumenta la DEF de todos los Aurorianos en un 1.5% después de ganar una batalla.",
  str_item_intro_9997032 = "Aumenta el ATQ de todos los Aurorianos en un 1% después de ganar una batalla.",
  str_item_intro_9997022 = "Número total de rondas +10 al obtener este objeto. ",
  str_item_intro_9997036 = "Al tocar para eliminar fichas, hay un 25% de posibilidad de aumentar el número de intentos de eliminación en 1.",
  str_item_intro_9997037 = "Al tocar para eliminar casillas, inflige aleatoriamente 1 pila de Envenenamiento, Sangrado o Ardor a los enemigos dentro del alcance de las casillas eliminadas.",
  str_item_intro_9997038 = "Al tocar para eliminar casillas, inflige daño igual al 120% del ATK promedio del equipo a los enemigos dentro del alcance de las casillas eliminadas.",
  str_item_intro_9997034 = "Los enemigos reciben daño igual al 150% del ATK promedio del equipo una vez por cada casilla que se mueven dentro del área de casillas que han sido tocadas y serán eliminadas en esta ronda.",
  str_item_intro_9997039 = "Al comienzo de la batalla, se puede usar 1 equipo especial de Caelestite aleatorio una vez.",
  str_item_intro_9997040 = "Obtén Equipo Especial de Caelestite: Convierte 2 fichas seleccionadas en fichas cromáticas. Esto se puede usar una vez por cada 60 fichas que se eliminan.",
  str_item_intro_9997041 = "Obtén Equipo Especial de Caelestite: Selecciona un área de 3x3 y elimina todas las casillas azules dentro de ella. Esto se puede usar una vez por cada 50 casillas que se eliminen.",
  str_item_intro_9997042 = "Obtén Equipo Especial de Caelestite: Selecciona un área de 3x3 y elimina todas las casillas rojas dentro de ella. Esto se puede usar una vez por cada 50 casillas que se eliminen.",
  str_item_intro_9997043 = "Obtén Equipo Especial de Caelestite: Selecciona un área de 3x3 y elimina todos los mosaicos verdes dentro de ella. Esto se puede usar una vez por cada 50 mosaicos que se eliminen.",
  str_item_intro_9997044 = "Obtén Equipo Especial de Caelestite: Selecciona un área de 3x3 y elimina todos los mosaicos amarillos dentro de ella. Esto se puede usar una vez por cada 50 mosaicos que se eliminen.",
  str_item_intro_9997045 = "Obtén Equipo Especial de Caelestite: Reinicia todas las casillas en el campo de batalla. Esto se puede usar una vez por cada 80 casillas eliminadas.",
  str_item_intro_9997046 = "Obtén Equipo Especial de Caelestite: Selecciona 1 color y reinicia todas las casillas de ese color en el campo de batalla. Esto se puede usar una vez por cada 80 casillas que se eliminen.",
  str_item_intro_9997047 = "Obtén Equipo Especial de Caelestite: Selecciona 1 casilla y elimina las 4 casillas más cercanas del mismo color. Esto se puede usar una vez cada 60 casillas que se eliminen.",
  str_item_rpintro_9997004 = "Auxiliar de poción de recuperación para ayudar a curar a los heridos.",
  str_item_rpintro_9997005 = "Arma clásica de la era antigua grabada con glifos bendecidos y particularmente efectiva contra enemigos ágiles.",
  str_item_rpintro_9997008 = "Estatua perfectamente conservada que proporciona poder curativo a quien la porta.",
  str_item_rpintro_9997009 = "Objeto de la era antigua que maldice al usuario y otorga un poder igual a cambio.",
  str_item_rpintro_9997010 = "Supuestamente un objeto misterioso de la guerra apocalíptica anterior. Lleva una poderosa maldición que es lo suficiente fuerte como para herir seriamente a los oponentes.",
  str_item_rpintro_9997011 = "Ponte esto para convertir la agonía en fuerza y, finalmente, alcanzar la victoria.",
  str_item_rpintro_9997012 = "Llévalo y estarás protegido por la Diosa de la Victoria, que te ganará todas tus batallas.",
  str_item_rpintro_9997013 = "Espada famosa de la era antigua, encantada con el poder del trueno. La ira explosiva se hace evidente al dibujar.",
  str_item_rpintro_9997014 = "Una joya que brilla en todos los col., espléndida y cambiante.",
  str_item_rpintro_9997015 = "Gran espada de la era antigua que, al sostenerla, puedes sentir cómo el poder dentro de ti crece.",
  str_item_rpintro_9997016 = "Arma clásica de la era antigua grabada con glifos bendecidos y particularmente efectiva contra enemigos ágiles.",
  str_item_rpintro_9997017 = "Arma clásica de la era antigua grabada con glifos bendecidos y particularmente efectiva contra enemigos ágiles.",
  str_item_rpintro_9997018 = "Antiguo cuchillo afilado hecho de súper aleación de la era antigua.",
  str_item_rpintro_9997019 = "The lenses glow in battle, blinding the opponent while protecting the wearer from it. Auxiliary equipment.",
  str_item_rpintro_9997020 = "Pintura antigua capaz de absorber Lumina.",
  str_item_rpintro_9997021 = "Old-era creation that seems very pretty but carries terrifying power, dropping enemies like falling flowers with explosions.",
  str_item_rpintro_9997023 = "Reliquia de la era antigua, posiblemente con una fuerte maldición. El usuario se vuelve letal con las toxinas.",
  str_item_rpintro_9997024 = "Espada famosa de la era antigua. El portador puede sentir un poder divino.",
  str_item_rpintro_9997025 = "Puede sentir la fuerte vitalidad del enemigo y acaba con aquellos que están cercas de la puerta de la muerte.",
  str_item_rpintro_9997026 = "Un cinturón muy ajustado que proporciona al usuario la Lumina necesaria cuando se activa bajo ciertos requisitos.",
  str_item_rpintro_9997027 = "Dispositivo desconocido de la era antigua que puede detectar y convertir Lumina desbordante en un campo de fuerza protector para el usuario.",
  str_item_rpintro_9997028 = "Supuestamente un objeto maldito creado por un poderoso guerrero para asegurar la perdición de todos los enemigos.",
  str_item_rpintro_9997029 = "Talismán para la era antigua, capaz de asegurar Lumina en un nivel micro, causando un gran daño a los enemigos.",
  str_item_rpintro_9997030 = "Artículo de la era antigua para regenerar cierta cantidad de Lumina para los Aurorians vinculados.",
  str_item_rpintro_9997031 = "Utiliza este objeto de la era antigua para recuperar rápidamente una parte de la Lumina perdida.",
  str_item_rpintro_9997033 = "Dispositivo para almacenar y reponer Lumina.",
  str_item_rpintro_9997035 = "Hoja de gran tamaño con maldad palpable. Probablemente utilizada para duelos a muerte en la antigüedad. Habrá sangre cuando se use.",
  str_item_rpintro_9997003 = "Vela que emite calor que puede curar a los Aurorians heridos.",
  str_item_rpintro_9997006 = "Estatuilla perdida de la era antigua hecha con material de alta calidad. Durable, ligera y bendice a quienes la portan.",
  str_item_rpintro_9997007 = "Escudo de la era antigua, en un óvalo perfecto y supuestamente infundido con el poder del sol para desviar todos los golpes letales.",
  str_item_rpintro_9997032 = "Insignia de la era antigua con una configuración maravillosa para asegurar Lumina en un nivel micro, mejorando la destreza de combate.",
  str_item_rpintro_9997022 = "Bolsa de dormir perdida y olvidada. Ayuda a recuperar fuerzas.",
  str_item_rpintro_9997036 = "Aparentemente escrito por eruditos antiguos, detalla los matices en el efecto de contador de elementos y proporciona sugerencias estratégicas efectivas.",
  str_item_rpintro_9997037 = "Cuadro antiguo de un pintor anónimo que retrata la atrocidad de la plaga. El artista también murió en la pandemía, tras lo cual su cuadro adquirió un poder aterrador...",
  str_item_rpintro_9997038 = "Un arma que parece ser capaz de fusionarse perfectamente con Lumina... Esto es realmente raro...",
  str_item_rpintro_9997034 = "Old-time item created specifically to deal with pursuers. Leaves Lumina on the trail that detonates later to kill the pursuers.",
  str_item_rpintro_9997039 = "Misteriosa moneda antigua que ocasionalmente aumenta la velocidad de su propietario Aurorian, otorgando más agilidad.",
  str_item_rpintro_9997040 = "Orquídeas rojas raras especialmente desarrolladas en la era antigua. Siempre aparecen, florecen y se marchitan en parejas. Parece formar un vínculo con el usuario y ayudar en el combate.",
  str_item_rpintro_9997041 = "Aparentemente un Colossus en miniatura de la era antigua que ayuda al propietario en la batalla.",
  str_item_rpintro_9997042 = "Aparentemente un Colossus en miniatura de la era antigua que ayuda al propietario en la batalla.",
  str_item_rpintro_9997043 = "Aparentemente un Colossus en miniatura de la era antigua que ayuda al propietario en la batalla.",
  str_item_rpintro_9997044 = "Aparentemente un Colossus en miniatura de la era antigua que ayuda al propietario en la batalla.",
  str_item_rpintro_9997045 = "Objeto de la era antigua que crea vínculos misteriosos entre dos combatientes.",
  str_item_rpintro_9997046 = "Cristal grueso con superficie ligeramente agrietada que indica exceso de Lumina en su interior. Solo un toque suave puede liberar suficiente Lumina para aturdir a los enemigos en una batalla.",
  str_item_rpintro_9997047 = "Tecnología antigua. Almacena mucho más Lumina de lo que indica su pequeño tamaño.",
  str_item_3000349 = "Token de Cloudrover",
  str_item_intro_3000349 = "Una ficha que se puede canjear por beneficios del Gremio de Explorador Nublar. Solo los clientes leales tienen la oportunidad de obtener esto.",
  str_item_3000134 = "Llamarada de estrella especial Avariciosa Lachesis",
  str_item_intro_3000134 = "Se puede usar para reclutar una vez del reclutamiento exclusivo actual.\nEste artículo caducará, así que utilícelo antes de que finalice el reclutamiento exclusivo actual de Avaricious Lachesis, o de lo contrario desaparecerá. No se convertirá en otro elemento cuando caduque.",
  str_item_3420133 = "Kit de reclutamiento de 2,5 años",
  str_item_intro_3420133 = "Elige un Aurorian de la siguiente lista de Aurorians de 6 estrellas para luchar a tu lado: <color=#ffffff>Dantang, Zarya, Antony, Lorelei, Cena, Joshua, Schwartz: Almighty Clamor, Yingel, Leo, Hati, Tina, Leyn, Jeriah, Mu Yuebai, Zhong Xu, Vic, Axelia, Lilica, Minos, Pollux, Jeno, Fia, Carleen: Smoldering Soul, Nina, Barton: Deft Blades, Giles, Lenore, Azure, Yao, Amemori, Rinne, Florine, Ruby, Siobhan, Novio, Hedy, Bethel, Luke, Paloma, Gram, Revy, Smokey, Fleur, Beryl, Hiiro, Sinsa, Eve, Uriel, Carleen, Sharona, Sariel, Raphael, Connolly, Charon, Eicy, Victoria, Jona, Nikinis, Gabriel, Migard, Michael, Gronru, Irridon, Wrath.</color>.Nota: este kit vencerá a las 09:00 del 28 de febrero de 2024 (UTC+0), 04:00 del 28 de febrero de 2024 (UTC-5). Reclámalo a tiempo o se convertirá automáticamente en 3000 Lumamber y se te enviará a través de tu buzón de correo del juego.",
  str_item_3661231 = "Trono Sombra",
  str_item_intro_3661231 = "Artículo de muebles. Se puede colocar en las habitaciones de tu Colossus.\nLa Guilda Cloudrover fabricó especialmente esta lujosa y dominante silla de cuero rígido para Istvan. Como es un producto tan llamativo, no ha habido escasez de compradores a pesar de su elevado precio.",
  str_item_3661232 = "Modelo de Dirigible Explorador Nublar",
  str_item_intro_3661232 = "Artículo de muebles. Se puede colocar en las habitaciones de su Colossus.\nDada la popularidad del Dirigible Cloudrover, un destino único que satisface todas sus necesidades de turismo, compras, recreación y vacaciones, es natural que haya modelos de este dirigible disponibles en varios tamaños para que los clientes los compren. Aunque este modelo en particular no es el más grande, está hecho con la más exquisita artesanía.",
  str_item_3661233 = "Luces Festivas",
  str_item_intro_3661233 = "Artículo de muebles. Se puede colocar en las habitaciones de su Colossus.\nIlumina espacios oscuros con filas de estas luces de colores. Esperemos que su luz tenue te brinde algo de calidez en este día digno de celebración.",
  str_item_3661234 = "Caja de Regalo Festiva",
  str_item_intro_3661234 = "Artículo de muebles. Se puede colocar en las habitaciones de tu Colossus.\nLos Aurorianos te han dado este regalo considerado. Aunque no vale mucho, su verdadero valor reside en el trabajo duro y el esfuerzo que representa. May este regalo te traiga buena suerte en el próximo año.",
  str_item_5234057 = "Carro de Hielo",
  str_item_intro_5234057 = "Un carro ornamental hecho de hielo. Su apariencia cristalina es extremadamente relajante y tranquilizadora.",
  str_item_3661236 = "Retrato de espadachín cambiando de atuendo",
  str_item_3661237 = "Retrato de espadachín en barco",
  str_item_3661241 = "Ventilador de Bool",
  str_item_3661242 = "Lámpara de planta",
  str_item_intro_3661236 = "Artículo de muebles. Se puede colocar en las habitaciones de su Colossus.\nObra de un cierto artesano, esta muñeca puede cambiar a otro atuendo aleatorio rápidamente con solo presionar un botón. Se dice que esta muñeca está inspirada en un tipo de arte de performance de Longzhou.\n\"Si quiero interpretar el papel de una persona de Longzhou... ¿también necesitaría aprender a cambiar mi atuendo instantáneamente como esto?\"",
  str_item_intro_3661237 = "Artículo de muebles. Se puede colocar en las habitaciones de tu Colossus.\nPara conmemorar la exitosa cooperación con el espadachín, el artesano hizo un retrato basado en la postura del espadachín al completar una misión.\n\"¿Quieres dejar el asiento del otro lado del barco vacío? Claro, solo dime cuándo quieres agregar a alguien allí.\"",
  str_item_intro_3661241 = "Artículo de muebles. Se puede colocar en las habitaciones de su Colossus.\nEste ventilador se utiliza exclusivamente en el laboratorio de los científicos de Illumina. Sus patas pueden doblarse de manera flexible o adherirse a superficies. Algunos dicen que este ventilador está inspirado en un robot llamado Bool.",
  str_item_intro_3661242 = "Artículo de muebles. Puede colocarse en las habitaciones de tu Colossus.\nUna lámpara exquisitamente diseñada que proporciona a las plantas la luz que necesitan para crecer y crea un ambiente cálido y natural en interiores.",
  str_item_3000352 = "Pluma Caelestita",
  str_item_intro_3000352 = "Se dice que esta pluma de aspecto único es extremadamente valiosa para los Caelestites.",
  str_item_3661243 = "Sofá Dumpling",
  str_item_3661244 = "Obra de Arte de Año Nuevo: El Dragón",
  str_item_3661238 = "Decoración de Petardos",
  str_item_3661239 = "Colgante de Año Nuevo",
  str_item_3661240 = "Estante pintoresco",
  str_item_intro_3661243 = "Artículo de muebles. Se puede colocar en las habitaciones de su Colossus.\nSofá perezoso con forma de dumpling, con una caja de voz que una vez estuvo viva con cánticos:\n\"¡Dumplings, un sinfín de dumplings!\"\n\"¡Hagamos todos dumplings juntos!\"\nAhora, el dispositivo de voz ha sido retirado por los Aurorianos cansados del ruido, restaurando la tranquilidad dentro del Colossus.",
  str_item_intro_3661244 = "Artículo de Mobiliario. Puede colocarse en las habitaciones de tu Colossus.\nUna pintura de Año Nuevo de la Doncella Dragón, un popular artículo festivo del Reino Ji. Pero este \"retrato artístico\" dado por Chen'ni es el único que retrata con precisión la apariencia de la Doncella Dragón.",
  str_item_intro_3661238 = "Artículo de muebles. Se puede colocar en las habitaciones de su Colossus.\nA medida que se acerca el festival tradicional de Longzhou, para que nuestros amigos de Longzhou en el Colossus sientan el ambiente festivo, todos en el Colossus cuelgan las decoraciones de petardos hechas en conjunto, con la esperanza de ahuyentar la mala suerte e invitar a la buena suerte.",
  str_item_intro_3661239 = "Artículo de muebles. Se puede colocar en las habitaciones de su Colossus.\nActualmente un superventas en la Bahía de Twin Pavilions, es una decoración imprescindible de Longzhou durante los tiempos festivos, simbolizando la esperanza de un futuro brillante.",
  str_item_intro_3661240 = "Artículo de muebles. Puede colocarse en las habitaciones de tu Colossus.\nElaborado por artesanos de la Bahía de los Pabellones Gemelos, este estante de madera está intrincadamente tallado y diseñado tanto para almacenamiento como para admiración, enriqueciendo las cámaras del Colossus con un toque de elegancia clásica.",
  str_item_intro_3763039 = "Desbloquea el marco de avatar correspondiente.\n\"Las flores de melocotón son delicadas y gráciles, irradiando su resplandeciente belleza. Y la fortuna llega, en su vibrante abrazo.\"",
  str_item_intro_3751417 = "Desbloquea el avatar correspondiente.\n\"¡Caelestite recibió un sombrero especial como regalo de Año Nuevo y se lo puso felizmente!\"",
  str_item_intro_3751566 = "Desbloquea el avatar correspondiente.\n\"¡Chen'ni otorga bendiciones, concediendo riqueza y prosperidad!\"\n¿Puede la Doncella Dragón, venerada como una deidad marina, realmente otorgar felicidad al mundo mundano? Chen'ni puede que no lo sepa, ¡pero está decidida a intentarlo!",
  str_item_intro_3751567 = "Desbloquea el avatar correspondiente.\n\"¡Mi paladar es el estándar!\"\nComo enviado de Astra, el Navegante tiene mucha experiencia en la degustación de alimentos, presumiendo de un paladar refinado.",
  str_item_intro_3763038 = "Desbloquea el marco de avatar correspondiente.\n\"¡Recolecta todas las Cartas de Primavera para invocar al dragón divino!\"\nNo estoy seguro si es cierto, pero esta locura de coleccionar cartas hizo que el Año Nuevo de Longzhou fuera mucho más divertido.",
  str_item_intro_3751413 = "Desbloquea el avatar correspondiente.\n\"Tengo una larga lista de cosas que me gustaría ver: la armadura mecanizada gigante en Azurite, los ruidosos espectáculos en el desierto, las intensas peleas subterráneas...\"\nIncluso una deidad tiene muchos deseos para el Año Nuevo.",
  str_item_intro_3751414 = "Desbloquea el avatar correspondiente.\n¡Cuidado con la bestia Nian de Umbraton, un verdadero devorador de hombres con largos cuernos! Echa un vistazo a \"Feria del Templo Prohibido\", la última película de terror de Alleywood, que se estrena esta primavera!\n\"Entonces... ¿cuál es mi papel de nuevo...?\"",
  str_item_intro_3751415 = "Desbloquea el avatar correspondiente.\n\"Aquí tienes, solo una pequeña cosa que preparé... ¡Puedo hacer cosas aparte de paletas, ya sabes!\"\nLa única cosa que Zarya logró hacer después de innumerables fracasos, con dulzura extra para manifestar sus sentimientos.",
  str_item_intro_3751416 = "Desbloquea el avatar correspondiente.\nEsperando que el reencuentro de hoy te brinde una sensación de hogar y fuerza. Es el mismo cielo sobre nosotros, estemos donde estemos.",
  str_item_intro_3751568 = "Desbloquea el avatar correspondiente.\n\"Aunque muchos expresan su cariño por mí, encuentro al Navegante el más especial. ¡Realmente compartimos una conexión de corazón a corazón!\"",
  str_item_intro_3751569 = "Desbloquea el avatar correspondiente.\n\"¿Corazón con la mano, en serio?... Bueno, toma este gesto mío y agradece... ¡pero no te emociones demasiado!\"",
  str_item_3763039 = "Flor de Fortuna",
  str_item_3751417 = "Caelestite con Sombrero de Dragón",
  str_item_3751566 = "Doncella Dragón de Longzhou en el Año del Dragón",
  str_item_3751567 = "Envío Foodie",
  str_item_3763038 = "Dragón de Primavera Elevándose",
  str_item_3751413 = "Deseo de Año Nuevo",
  str_item_3751414 = "Conjunto Festivo",
  str_item_3751415 = "Dulce Delicia",
  str_item_3751416 = "Gran Reunión",
  str_item_3751568 = "Consideración de Fleur",
  str_item_3751569 = "La Mirada de Zarya",
  str_item_3763041 = "Corona de Mil Días",
  str_item_3751420 = "Día del Caballero de la Corona de Luna",
  str_item_3751419 = "Abarcando mil noches",
  str_item_3751570 = "Limbo en Llamas",
  str_item_3763040 = "Resplandor Final",
  str_item_3751421 = "Corazón de Mil Días",
  str_item_3751422 = "Flecha de Gotas de Amor",
  str_item_intro_3751421 = "Desbloquea el avatar correspondiente.\n\"¡Navegante, por aquí!\"\nEl amor ha sido tu compañero constante en este viaje de mil días. ¡Sigue adelante con las bendiciones de todos!",
  str_item_intro_3751422 = "Desbloquea el avatar correspondiente.\n\"¡Aprovecha el momento; hoy podría ser el punto de inflexión en nuestro destino!\"",
  str_item_intro_3763041 = "Desbloquea el marco de avatar correspondiente.\n\"¡Aquellos que son firmes serán recompensados con gloria!\"\nGracias por tu guía y protección durante mil días de perseverancia y compañía. Esperamos futuras aventuras juntos.",
  str_item_intro_3751420 = "Desbloquea el avatar correspondiente.\n\"¿También quieres participar en la prueba especial del Día de la Coronación Lunar?\"",
  str_item_intro_3751419 = "Desbloquea el avatar correspondiente.\nNavegante, gracias por acompañarme durante mil días bajo este cielo. ¡Por favor, continúa guiándome en el futuro!",
  str_item_intro_3751570 = "Desbloquea el avatar correspondiente.\n\"¿Quieres estar en el Limbo conmigo? Toma mi mano entonces, ¡y dejemos que nuestras esperanzas brillen intensamente!\"",
  str_item_intro_3763040 = "Desbloquea el marco de avatar correspondiente.\n\"Mi atuendo estallará en llamas cuando la poción se desvanezca. ¿Seguirás el último rastro de la llama hasta mí?\"",
  str_item_3751042 = "Mensajes del Viajero",
  str_item_3751043 = "Frutos del Entrenamiento",
  str_item_3751044 = "La Verdad Perdura",
  str_item_3751045 = "Guardián en el Viaje",
  str_item_3751046 = "Regular de la Fiesta del Té",
  str_item_3751047 = "Mi historia",
  str_item_3751048 = "Hermanos de Armas",
  str_item_3751573 = "Ocultando Fox",
  str_item_3763042 = "Croaker superior",
  str_item_intro_3751042 = "Desbloquea el avatar correspondiente.\n\"Entiendo lo difícil que es el camino para un Navegante. Sigue con el buen trabajo.\"",
  str_item_intro_3751043 = "Desbloquea el avatar correspondiente.\n\"Resistir durante tanto tiempo es realmente encomiable. ¡Sigamos entrenando juntos en el futuro!\"",
  str_item_intro_3751044 = "Desbloquea el avatar correspondiente.\n\"Siempre recuerda: no importa cómo cambie el tiempo, la verdad perdura.\"",
  str_item_intro_3751045 = "Desbloquea el avatar correspondiente.\n\"En los viajes que vendrán, siempre te mantendré a salvo.\"",
  str_item_intro_3751046 = "Desbloquea el avatar correspondiente.\n\"¿Cuántas veces te he invitado a tomar el té de la tarde?\"",
  str_item_intro_3751047 = "Desbloquea el avatar correspondiente.\n\"He compartido mi historia contigo; ¿cuál es la tuya?\"",
  str_item_intro_3751048 = "Desbloquea el avatar correspondiente.\n\"¡Después de tanto tiempo juntos, ya somos verdaderos hermanos!\"",
  str_item_intro_3751573 = "Desbloquea el avatar correspondiente.\n\"¿Ya terminaste de esconderte?\" \"Todavía no.\"",
  str_item_intro_3763042 = [[
Desbloquea el marco de avatar correspondiente.
"Parece algo familiar."]],
  str_item_intro_3751423 = "Desbloquea el Avatar correspondiente.\n\"¡Croac! ¡Croac!! ¡Croac!!!\"",
  str_item_intro_3751424 = "Desbloquea el avatar correspondiente.\n\"¿Qué debería hacer... La respuesta siempre ha estado en mi corazón?\"",
  str_item_3751423 = "Príncipe Lilypad",
  str_item_3751424 = "Respuestas Debajo del Faro",
  str_item_3440014 = "Bolsa de maravilla",
  str_item_intro_3440014 = "Solo soy una pobre rana que te ha dado todos mis ahorros de toda la vida.",
  str_item_intro_3440015 = "Las recompensas ofrecidas en la bolsa de fortuna de súper valor suelen ser engañosas.",
  str_item_intro_3440016 = "La buena suerte asciende de manera escalonada, al igual que mi vida.",
  str_item_intro_3440017 = "Haz un sorteo más; parece que estamos cerca de la recompensa garantizada.",
  str_item_intro_3440018 = "¡Este es mi último intento! Luego simplemente tocaré Atrás, cerraré la pantalla y saldré del juego.",
  str_item_3751574 = "Presentando: Goldie el ídolo",
  str_item_intro_3751574 = "Desbloquea el avatar correspondiente.\n\"Todos la miran; ella es el epítome de la perfección y la radiación, la ídolo definitiva.\"",
  str_item_3751425 = "Cansancio del Ídolo",
  str_item_intro_3751425 = "Desbloquea el avatar correspondiente.\n\"¡Bostezo! Me siento tan somnoliento desde el momento en que me puse este pijama.\"",
  str_item_3763043 = "Malvavisco que escogí",
  str_item_intro_3763043 = [[
Desbloquea el marco de avatar correspondiente.
"La figura elegante encanta con su adorable pelusa, atrapando a otro en su encantadora red."]],
  str_item_3751572 = "¿Dónde está Papá",
  str_item_intro_3751572 = "Desbloquea el avatar correspondiente.\n\"Papá, por favor infórmame de tu ubicación actual.\"",
  str_item_3751571 = "Bendición de Sonrisas",
  str_item_intro_3751571 = "Desbloquea el avatar correspondiente.\n\"Regalo este componente a Papá, deseando que su expresión se alinee con la que se muestra en la pantalla.\"",
  str_item_3751429 = "Hola Toto",
  str_item_intro_3751429 = "Desbloquea el avatar correspondiente.\n\"Hola, Toto! El cálido Colossus acoge a todo trabajador con el corazón roto.\"",
  str_item_3751430 = "Insignias y Honor",
  str_item_3751577 = "¡Escuadrón Eagleeye, reúnanse!",
  str_item_3751578 = "Confeti de Carnaval",
  str_item_3751579 = "Compañerismo Eterno",
  str_item_3763046 = "Grandes Bendiciones",
  str_item_3763047 = "Koinobori",
  str_item_intro_3751430 = "Desbloquea el avatar correspondiente.\n\"Muy bien. No manché mi honor hoy.\"",
  str_item_intro_3751577 = "Desbloquea el avatar correspondiente.\n\"Tu mirada debe ser aguda como la de un halcón, tus ataques deben ser tan afilados como sus garras, y tus movimientos deben ser tan rápidos como sus alas aleteando.\"",
  str_item_intro_3751578 = "Desbloquea el avatar correspondiente.\n\"Dilo conmigo: ¡FELIZ CARNAVAL!\"",
  str_item_intro_3751579 = "Desbloquea el avatar correspondiente.\n\"May todas las cosas en este mundo se prestan para la realización de tus deseos por toda la eternidad.\"",
  str_item_intro_3763046 = "Desbloquea el marco de avatar correspondiente.\n\"¡Deseo que todo vaya a tu favor. Deseo que seas imparable. Deseo que logres todo lo que deseas. Deseo que siempre perseveres. Deseo que siempre estés conmigo para que podamos compartir aún más momentos felices juntos!\"",
  str_item_intro_3763047 = "Desbloquea el marco de avatar correspondiente.\nEsta pancarta de tótem que es popular en toda la Isla de la Nube es un símbolo de crecimiento y coraje.",
  str_item_3751581 = "Sensaciones conmovedoras",
  str_item_3751582 = "Ñam-Ñam",
  str_item_3751580 = "Dueño de Hidden Fangs",
  str_item_intro_3751581 = "Desbloquea el avatar correspondiente.\n\"Oh, ¿es esto... lo que se siente al ser amado por alguien?\"",
  str_item_intro_3751582 = "Desbloquea el avatar correspondiente.\n\"Un bocado más... ¡Sí, un bocado más!\"",
  str_item_intro_3751580 = "Desbloquea el Avatar correspondiente.\n\"Soy el dueño de Hidden Fangs en Umbraton. ¡Bienvenido al mundo de los juegos!\"",
  str_item_3751436 = "Mirada Determinada",
  str_item_3751583 = "Llamas de Rebelión",
  str_item_3751584 = "Invitado de Honor",
  str_item_3751585 = "Brindis por Nuestra Amistad",
  str_item_3763048 = "Perspectivas Futuras de Illumina",
  str_item_3763049 = "Llave de la Tumba Secreta",
  str_item_intro_3751436 = "Desbloquea el avatar correspondiente.\n\"¡Es maravilloso tenerlos a todos aquí!\"",
  str_item_intro_3751583 = "Desbloquea el avatar correspondiente.\n\"Necesitarás ser más fuerte. Más fuerte que los Aurorians más fuertes del mundo.\"",
  str_item_intro_3751584 = "Desbloquea el avatar correspondiente.\n\"Incluso si muero hoy, aún quiero ver tu verdadero rostro.\"",
  str_item_intro_3751585 = "Desbloquea el avatar correspondiente.\n\"Acercarse a él es perfectamente aceptable, pero pido que se comporten con un poco más de dignidad. Después de todo, él está aquí a mi petición.\"",
  str_item_intro_3763048 = "Desbloquea el marco de avatar correspondiente.\n\"Pero no te preocupes. Nada puede permanecer igual siempre, y aunque algunos cambios realmente pueden agobiarnos, la mayoría de las veces, el cambio es emocionante.\"",
  str_item_intro_3763049 = "Desbloquea el marco de avatar correspondiente.\n\"¿Puede uno revelar los secretos custodiados por la Caja Negra con la tenue luz de una simple vela?\"",
  str_item_3751438 = "Perspicacia de la Verdad",
  str_item_3751586 = "Iluminado",
  str_item_3763050 = "Camino Brillante",
  str_item_intro_3751438 = [[
Desbloquea el avatar correspondiente.
"Los buscadores de la verdad son como aquellos que persiguen estrellas lejanas; requieren ojos sinceros para ver la luz."]],
  str_item_intro_3751586 = "Desbloquea el avatar correspondiente.\n\"¡Confieso! ¡Expió! Yo... Yo soy el bendecido por la verdad.\"",
  str_item_intro_3763050 = "Desbloquea el marco de avatar correspondiente.\n\"May la Verdad te bendiga, y May tu vida de aquí en adelante brille intensamente.\"",
  str_item_3751426 = "Aura de Ryza",
  str_item_3751427 = "La sonrisa de Klaudia",
  str_item_3751428 = "La Tenacidad de Patricia",
  str_item_3751575 = "Hacia una Nueva Aventura",
  str_item_3751576 = "Espléndida Flor de Verano",
  str_item_3751587 = "Rey Naval Ambicioso",
  str_item_3751588 = "Drone Acuático",
  str_item_3763044 = "Ensueño espumoso",
  str_item_3763045 = "Brisa marina brillante",
  str_item_3763051 = "Captura el Verano",
  str_item_3763052 = "Sucio Rico",
  str_item_3763053 = "Juramento Angel",
  str_item_3751444 = "Por favor, diviértete.",
  str_item_3751443 = "El Elfo en el Mar",
  str_item_3751589 = "Princesa de cuento de hadas",
  str_item_3751594 = "Cazador de Acheron",
  str_item_3751593 = "Serpiente Dorada",
  str_item_3751592 = "Lector de Juramentos",
  str_item_3751591 = "Claymore",
  str_item_intro_3751594 = [[
Desbloquea el avatar correspondiente.
"Las alas negras cortan el cielo sobre el Aqueronte como una hoja afilada."]],
  str_item_intro_3751593 = "Desbloquea el avatar correspondiente.\n\"Ya sea por negocios o solo por diversión, con suficiente oro, ¡estoy a tu servicio!\"",
  str_item_intro_3751592 = "Desbloquea el avatar correspondiente.\n\"El juramento milenario no será olvidado. Un símbolo de gratitud del clan Longinus, otorgado solo a aquellos que completan el viaje de un verdadero héroe\".",
  str_item_intro_3751591 = "Desbloquea el avatar correspondiente.\n\"No muestres piedad, mi espada está aquí para proteger los cuentos de las estrellas.\"",
  str_item_intro_3763052 = "Desbloquea el marco de avatar correspondiente.\n\"¡El oro es deslumbrante!\"",
  str_item_intro_3763053 = [[
Desbloquea el marco de avatar correspondiente.
"Las alas negras son las guardianas de un juramento milenario."]],
  str_item_intro_3751444 = "Desbloquea el avatar correspondiente.\n\"Mira a los competidores, totalmente comprometidos y luchando por sus rangos. ¡Por favor, disfruta de este juego y muestra tu apoyo!\"",
  str_item_intro_3751443 = "Desbloquea el avatar correspondiente.\n\"Me encanta el agua y amo nadar. ¿Debería unirme a la competencia y divertirme con todos?\"",
  str_item_intro_3751589 = "Desbloquea el avatar correspondiente.\n\"Quiero tener un sueño hermoso, donde no hay tristeza y la felicidad dura para siempre...\"",
  str_item_intro_3751426 = "Desbloquea el avatar correspondiente.\n\"¿Qué es esto? Qué conmovedor...\"",
  str_item_intro_3751427 = "Desbloquea el avatar correspondiente.\n\"Bienvenido de nuevo. ¿Cómo fue tu aventura? ¿Viste algo particularmente interesante?\"",
  str_item_intro_3751428 = "Desbloquea el avatar correspondiente.\n\"Ah, lo siento por dejarte ver un lado tan vergonzoso de mí. Me aseguraré de mantener la compostura la próxima vez.\"",
  str_item_intro_3751575 = "Desbloquea el avatar correspondiente.\n\"¡Rumbo a una nueva aventura!\"",
  str_item_intro_3751576 = "Desbloquea el avatar correspondiente.\n\"¡Pasar el verano con amigos es lo mejor!\"",
  str_item_intro_3751587 = "Desbloquea el avatar correspondiente.\n\"Ya que esta terquedad puede conquistar la tierra, enfrentarse al mar no debería ser un problema... ¿verdad?\"",
  str_item_intro_3751588 = "Desbloquea el avatar correspondiente.\n\"Beep-beep, activando el modo de navegación acuática...\"",
  str_item_intro_3763044 = "Desbloquea el marco de avatar correspondiente.\n\"Todos los que se bañan en esta luz sentirán que sus corazones se vuelven más brillantes.\"",
  str_item_intro_3763045 = "Desbloquea el marco de avatar correspondiente.\n\"¡Venir a Astra es el accidente más sorprendente de este verano!\"",
  str_item_intro_3763051 = "Desbloquea el marco de avatar correspondiente.\n\"Un aro de natación a la moda que hace que uno anhele el mar a primera vista. ¡No te pierdas el verano fugaz, actúa rápido y úsalo para abrazar la temporada!\"",
  str_item_3661248 = "Estatua del Héroe antiguo",
  str_item_3661249 = "Estatua del Oficial antiguo",
  str_item_intro_3661248 = "Artículo de muebles. Se puede colocar en las habitaciones de su Colossus.\nUna antigua estatua, recientemente desenterrada e identificada como un guerrero civil honrado en tiempos pasados basado en su atuendo y tocado. Los arqueólogos señalan que solo los nobles tenían el derecho de encargar sus estatuas durante esa era, lo que significa que debió haber logrado hazañas tan notables que la gente creó esta estatua en admiración.\n\"¡Protegeré el mundo que ella apreciaba!\"",
  str_item_intro_3661249 = "Artículo de muebles. Se puede colocar en las habitaciones de su Colossus.\nUna antigua estatua, recientemente desenterrada e identificada como un oficial de alto rango en el ejército basado en su atuendo y tocado. Los arqueólogos señalan que los oficiales militares eran casi exclusivamente de noble cuna durante esa era. Por lo tanto, a diferencia de la estatua de un guerrero civil, esta probablemente provino de las manos de un escultor dedicado a servir a la nobleza.\n\"Deja el resto a mí; me encargaré de ello.\"",
  str_item_3661250 = "Estatua de Fox Nieve",
  str_item_3661251 = "Candelero de pino",
  str_item_3661252 = "La estantería de Robyn",
  str_item_3661253 = "Estéreo de coleccionista",
  str_item_3661254 = "Mesa baja de ocio",
  str_item_intro_3661250 = "Artículo de Mobiliario. Puede colocarse en las habitaciones de tu Colossus.\nUna estatua muy querida entre los habitantes de Northland, supuestamente modelada a partir de un guardia de Northland, creada para honrar a un camarada significativo perdido en batalla.",
  str_item_intro_3661251 = "Artículo de muebles. Se puede colocar en las habitaciones de su Colossus.\nHecho del mejor pino, este candelabro atmosférico libera una delicada fragancia de pino, ayudando en la relajación y el sueño.",
  str_item_intro_3661252 = "Artículo de muebles. Se puede colocar en las habitaciones de su Colossus.\nUna estantería de forma simple hecha de madera de alta calidad, exuda una fragancia sutil.",
  str_item_intro_3661253 = "Artículo de muebles. Se puede colocar en las habitaciones de su Colossus.\nUn elegante estéreo perfecto para eventos solemnes. Su tono es más adecuado para una procesión ceremonial que para la música de heavy metal que Ansia ama.",
  str_item_intro_3661254 = "Artículo de muebles. Se puede colocar en las habitaciones de su Colossus.\nUna mesa elegante y económica perfecta para momentos de ocio de los residentes urbanos, un superventas en cualquier lugar.",
  str_item_3661256 = "Reloj antiguo",
  str_item_3661257 = "Pintura decorativa de noche a la luz de la luna",
  str_item_3661258 = "Peluche Harehound",
  str_item_3661260 = "Parrilla Rediesel",
  str_item_intro_3661256 = "Artículo de muebles. Se puede colocar en las habitaciones de su Colossus.\nEl marco de metal de este reloj está elegantemente elaborado, y su cara ha sido tratada especialmente para producir un lustre de bronce con el tiempo.",
  str_item_intro_3661257 = "Artículo de muebles. Se puede colocar en las habitaciones de su Colossus.\nUna hermosa pintura decorativa de la luna contra el cielo nocturno. Desde el centro de la pintura, emite un brillo suave y delicado.",
  str_item_intro_3661258 = "Artículo de muebles. Se puede colocar en las habitaciones de su Colossus.\nUn muñeco en forma de beagle. Sus ojos parecen decir: \"Lo veo, lo quiero, ¡y tengo que tenerlo!\"",
  str_item_intro_3661260 = "Artículo de muebles. Se puede colocar en las habitaciones de su Colossus.\nLa parrilla más común que se encuentra en los campamentos de Rediesel Wrench. Aunque en gran parte está construida con chatarra, esta parrilla le da a la comida un sabor irresistiblemente carbonizado, o al menos eso parece pensar Rediesel Wrench.",
  str_item_3661265 = "Retrato elegante del viajero",
  str_item_3661266 = "Estatua grotesca de zanahoria",
  str_item_intro_3661265 = "Artículo de muebles. Se puede colocar en las habitaciones de tu Colossus.\nLas leyendas hablan de un viajero que construyó la dulce ciudad de Folta en una tierra de interminable leche y miel...\n\"¿Dónde exactamente está esta ciudad? ¿Podría ser... en un mundo completamente diferente?\"",
  str_item_intro_3661266 = "Artículo de muebles. Se puede colocar en las habitaciones de su Colossus.\nPara los niños que odian comer zanahorias, sus ojos verdes brillantes y garras afiladas son más aterradores que cualquier Eclipsite...\n\"Po... Pero yo soy Popo, una pobre y pequeña zanahoria...\"",
  str_item_3661267 = "Juego de Arcade Retro",
  str_item_intro_3661267 = "Artículo de muebles. Se puede colocar en las habitaciones de tu Colossus.\n\"Si voy a quedarme a bordo del Colossus, entonces tengo que traer esto... O no sobreviviré.\"\nAnte tal solicitud, el Navegante estuvo más que dispuesto a arriesgar algunos músculos para complacer a su amigo.",
  str_item_3661268 = "Decoración de pared de gafas de sol Pixel",
  str_item_intro_3661268 = "Artículo de muebles. Se puede colocar en las habitaciones de su Colossus.\n\"Has perdido, Yingel. Deja los despojos atrás.\"\nUn premio bien ganado obtenido después de derrotar a Yingel. Parece mercancía de un juego.",
  str_item_3661271 = "Caja de almacenamiento de muñecas",
  str_item_intro_3661271 = "Artículo de muebles. Se puede colocar en las habitaciones de su Colossus.\nPara los coleccionistas de peluches que tienden a perder la pista de sus pertenencias, esta es posiblemente la mayor invención del mundo.",
  str_item_3661272 = "Reloj de Pata de Gato",
  str_item_intro_3661272 = "Artículo de muebles. Se puede colocar en las habitaciones de su Colossus.\nUn reloj de pared supremamente adorable en forma de pata de gato. Es casi una pena tener que colgar algo tan suave y apretujable en la pared.",
  str_item_3661273 = "Podio de Novato",
  str_item_intro_3661273 = "Artículo de muebles. Se puede colocar en las habitaciones de su Colossus.\nActualmente se está extendiendo un cierto rumor por Illumina: los nuevos estudiantes que gritan sus sueños desde un podio se convertirán en héroes respetados algún día.",
  str_item_3661274 = "Chimenea de hierro fundido",
  str_item_intro_3661274 = "Artículo de muebles. Se puede colocar en las habitaciones de su Colossus.\nUna chimenea de hierro fundido producida en la Federación Illumina. Aparte de su respetable capacidad de calefacción, su apariencia pintoresca y sus cálidas llamas aportan una comodidad innegable a cualquier habitación.",
  str_item_3661275 = "Alfombra de Iluminación",
  str_item_intro_3661275 = "Artículo de muebles. Se puede colocar en las habitaciones de tu Colossus.\nRopa de cama de alta gama de la ciudad de Varaki. Cómoda y acogedora, tiene un aire clásico distintivo. Los discípulos de la Verdadera Orden lo consideran una cama de revelación divina.",
  str_item_3661276 = "Espejo del Mañana",
  str_item_intro_3661276 = "Artículo de muebles. Se puede colocar en las habitaciones de su Colossus.\n\"Aquellos que buscan la verdad deben mirar en este antiguo espejo de madera y contemplar visiones de lo que está por venir.\" En serio, ¿quién inventa estas cosas...?",
  str_item_3661277 = "Retrato del valiente soldado",
  str_item_intro_3661277 = "Artículo de muebles. Se puede colocar en las habitaciones de su Colossus.\nEl rugido abrumador de los Eclipsites atacantes ahogó incluso la señal de la corneta para cargar. Pero cuando un soldado heroico izó el estandarte y avanzó, miles de otros lo siguieron de cerca.\n\"Dedicado a esos héroes sin miedo que valientemente dieron sus vidas.\"",
  str_item_3661278 = "Estatua de la Campana del Día del Juicio Final",
  str_item_intro_3661278 = "Artículo de muebles. Se puede colocar en las habitaciones de su Colossus.\nUna estatua repulsiva y aterradora. Su apariencia malévola lleva a las personas a creer que fue creada como un enemigo del mundo.\nSe dice que mientras avanzaba pesadamente, la armadura de metal que llevaba chocaba sordamente, el rencoroso requiem de la campana del atardecer.",
  str_item_3661262 = "Modelo de Guardián de Ruinas",
  str_item_intro_3661262 = "Artículo de muebles. Se puede colocar en las habitaciones de su Colossus.\nUn modelo elaborado por Fleur, quien siempre está pensando en el guardián de las ruinas.\n\"¡Probablemente podría considerarse un tipo de mecha!\"",
  str_item_3661263 = "Caldero de alquimia",
  str_item_intro_3661263 = "Artículo de muebles. Se puede colocar en las habitaciones de su Colossus.\nCon esto, el Atelier de Ryza en el Colossus finalmente puede abrir para negocios!",
  str_item_3661264 = "Imagen residual de la aventura",
  str_item_intro_3661264 = "Artículo de muebles. Se puede colocar en las habitaciones de su Colossus.\n¡Recordemos este verano una vez que haya terminado!",
  str_item_3661279 = "Casco de Brisa de Verano",
  str_item_intro_3661279 = "Artículo de muebles. Puede colocarse en cuartos de tu Colossus. Con ambas manos sobre él, uno puede casi sentir la caricia de la brisa marina, capturando perfectamente la esencia fresca del océano en verano. Un mueble esencial para cualquier entusiasta de la navegación.",
  str_item_3661280 = "Anillo de Natación Brisa de Verano",
  str_item_intro_3661280 = "Artículo de muebles. Se puede colocar en las habitaciones de su Colossus.\nDiseñado con una combinación de colores clásica y una estructura robusta, ya sea colocado en el hogar o utilizado en el mar, siempre es una vista encantadora.",
  str_item_3661281 = "Banner de Brisa de Verano",
  str_item_intro_3661281 = "Artículo de muebles. Se puede colocar en las habitaciones de su Colossus.\nUna pancarta decorativa simple pero elegante, adecuada para cualquier espacio que requiera un toque náutico.",
  str_item_3661282 = "Cuidador de Aves Marinas Concha",
  str_item_intro_3661282 = "Artículo de muebles. Se puede colocar en las habitaciones de su Colossus.\n\"Gran concha, toot-toot-toot. Las gaviotas la escuchan y caen del cielo.\"\nNo se sabe con certeza el origen, pero esta canción se ha estado difundiendo en el Colossus.",
  str_item_3661283 = "Lanzador de Burbujas Brisa",
  str_item_intro_3661283 = "Artículo de muebles. Se puede colocar en las habitaciones de su Colossus.\nUna pistola de burbujas fijada en una base, parece soplar burbujas con una sola presión.\n\"¡Qué accesorio tan casual! Esperemos que no haga dormir a todos.\"",
  str_item_3661284 = "Retrato de Narciso Blanco",
  str_item_intro_3661284 = "Artículo de muebles. Se puede colocar en las habitaciones de tu Colossus.\nNikinis ama cultivar flores de narciso. Ella cuida profundamente de sus plantas y lanzará a cualquiera que las pisotee al Lago Espejo.",
  str_item_3661285 = "Retrato Puro de Lirio",
  str_item_intro_3661285 = "Artículo de muebles. Se puede colocar en las habitaciones de tu Colossus.\nA Nepolis le gusta cultivar lirios. A menudo los cosecha para darlos como regalos, dejando solo su dulce fragancia detrás.",
  str_item_3661286 = "Resplandor Estelar",
  str_item_intro_3661286 = "Artículo de muebles. Se puede colocar en las habitaciones de su Colossus.\nLa pintura de Mithra: la sonrisa fugaz de Aquiles.\nEstrella inquebrantable, que tú y tus compañeros brillen con fuerza de nuevo.",
  str_item_3661287 = "Cuchillas dobles",
  str_item_intro_3661287 = "Artículo de muebles. Se puede colocar en las habitaciones de su Colossus.\nRéplicas de las armas utilizadas por el capitán y el vicecapitán del Cazador Silencioso.\n¡Contempla! Esto es el pináculo de la innovación y la determinación para proteger! Eso es lo que representan los Cazadores Silenciosos.",
  str_item_3661288 = "Puesto de depredador",
  str_item_intro_3661288 = "Artículo de muebles. Se puede colocar en las habitaciones de su Colossus.\nUn posadero que Mithra preparó para el depredador.\nPueden parecer tranquilos allí arriba, pero esas garras no son ninguna broma.",
  str_item_3661289 = "Unidad Starbound",
  str_item_intro_3661289 = "Artículo de muebles. Se puede colocar en las habitaciones de su Colossus.\nUna pieza antigua que ha sido restaurada.\nSi las estrellas que surcan el cielo pudieran algún día encontrar donde pertenecen en la suavidad del tiempo...\nMay recibes felicidad tardía.",
  str_item_3661290 = "Melodía a la luz de la luna",
  str_item_intro_3661290 = "Artículo de muebles. Se puede colocar en las habitaciones de su Colossus.\nUna melodía de Ludweiss, un Caelestite.\nEs pura y elegante como la luz de la luna, con un toque de tristeza inquebrantable. May recibes felicidad tardía.",
