  str_item_9011075 = "Corazón del territorio secreto",
  str_item_9011076 = "Estatua de la amistad",
  str_item_9011077 = "Hacha de berserker",
  str_item_9011078 = "Martillo de guerra del berserker",
  str_item_9011079 = "Alma berserker",
  str_item_9011080 = "Armadura de berserker",
  str_item_9011081 = "Guanteletes de berserker",
  str_item_9011082 = "Botas de hierro del berserker",
  str_item_9011083 = "Garras Lunares",
  str_item_9011084 = "Machete Silvermoon",
  str_item_9011085 = "Arco de Silvermoon",
  str_item_9011086 = "Escudo de Silvermoon",
  str_item_9011087 = "Cuchillas de Brazo Lunar",
  str_item_9011088 = "Cuerno lunar",
  str_item_intro_9011001 = "Al inicio de la ronda, inflige 4,444 de daño fijo a todos los enemigos y elimina a aquellos con menos del 6% de HP.",
  str_item_intro_9011002 = "Genera mosaicos cromáticos en el área circundante cada ronda, con la cantidad igual al número de tipos de Elemento Primario de los Aurorianos en el equipo. La habilidad se ejecuta 2 veces más al comienzo de la batalla.",
  str_item_intro_9011003 = "Convierte todas las fichas a cromáticas en la tercera ronda de batalla. Después de que finaliza la conexión de fichas, todas las fichas cromáticas serán eliminadas.",
  str_item_intro_9011004 = "Aumenta el daño infligido por los Aurorianos con HP igual a su máximo en un 15%.",
  str_item_intro_9011005 = "Después de completar la etapa del Devorador de Sueños, obtienes intereses equivalentos al 30% de tus monedas de sueño actuales.",
  str_item_intro_9011006 = "Uso único: Gana 2 Bombas de Sueño.",
  str_item_intro_9011007 = "Cuantas más Monedas de Sueño poseas, mayor será el daño que tus ataques normales infligen.",
  str_item_intro_9011008 = "La primera ficha en una línea puede tener un color diferente al de las siguientes, permitiendo que ambos tipos de Aurorianos se unan a la batalla.",
  str_item_intro_9011009 = "Aleatoriza todas las Esferas de Sueño desequipadas en nuevas (sin un nivel inferior al original) y cada Esfera de Sueño tiene un 30% de probabilidad de aumentar en calificación.",
  str_item_intro_9011010 = "Cuando el color de las casillas conectadas coincide con el elemento del Capitán, el Orbe de Sueño gana 1 carga por cada 2 casillas conectadas.",
  str_item_intro_9011011 = "Cuando las habilidades de Dream Orb infligen daño, realizan dos cálculos aleatorios dentro de un rango y eligen el valor más alto como el daño infligido, ampliando el rango de fluctuación del daño en un 10%.",
  str_item_intro_9011012 = "Establece la calificación de las Orbes de Sueño obtenidas posteriormente en 1 estrella.",
  str_item_intro_9011013 = "Al seleccionar una Tarjeta de Adivinación de Sueños, disminuye las opciones disponibles en 1 pero duplica los efectos de recompensa de las tarjetas.",
  str_item_intro_9011014 = "Disminuye el HP máximo de todos los Aurorianos en un 20% después de entrar en combate, pero aumenta el número de Cartas de Adivinación de Sueños seleccionables en +1 durante las acciones.",
  str_item_intro_9011015 = "Antes de conectar las fichas, cada vez que un auroriano se mueve, inflige daño a un área en forma de diamante en el lugar de aterrizaje, promediando el 150% de su ATK. Además, el Orbe de Sueño gana 1 carga por cada círculo de movimiento.",
  str_item_intro_9011016 = "Cuando los Combos en Cadena de los Aurorians Convertidores y de Apoyo causan daño, infligen aleatoriamente una acumulación de Envenenado, Sangrado o Quemado en el objetivo.",
  str_item_intro_9011017 = "Al infligir daño a enemigos Envenenados, Sangrando o Quemándose, aumenta el daño para cada efecto.",
  str_item_intro_9011018 = "Después de infligir una acumulación de Envenenamiento, Sangrado o Ardor al objetivo, existe la posibilidad de aplicar otra acumulación de debilitamiento aleatorio. Este efecto puede activarse repetidamente, con la probabilidad reducida a la mitad cada vez.",
  str_item_intro_9011019 = "Cuando un enemigo muere, aplica aleatoriamente una acumulación de Envenenado, Sangrado o Ardor a todos los enemigos.",
  str_item_intro_9011020 = "Al lanzar ataques normales, el Capitán inflige daño adicional de Fuego equivalente al 50% del ATK total del equipo.",
  str_item_intro_9011021 = "Al lanzar ataques normales, el Capitán inflige daño adicional de Trueno equivalente al 50% del ATK total del equipo.",
  str_item_intro_9011022 = "Al lanzar ataques normales, el Capitán inflige daño adicional de Bosque equivalente al 50% del ATK total del equipo.",
  str_item_intro_9011023 = "Al lanzar ataques normales, el Capitán inflige daño adicional de agua equivalente al 50% del ATK total del equipo.",
  str_item_intro_9011024 = "Al comienzo de cada ronda, convierte las 3 fichas rojas más cercanas en fichas cromáticas.",
  str_item_intro_9011025 = "Al comienzo de cada ronda, convierte las 3 fichas amarillas más cercanas en fichas cromáticas.",
  str_item_intro_9011026 = "Al comienzo de cada ronda, convierte las 3 fichas verdes más cercanas en fichas cromáticas.",
  str_item_intro_9011027 = "Al comienzo de cada ronda, convierte las 3 fichas azules más cercanas en fichas cromáticas.",
  str_item_intro_9011028 = "Al comienzo de cada ronda, convierte hasta 1 mosaico debajo de cada enemigo en cromático.",
  str_item_intro_9011029 = "Al recibir daño, convierte 3 mosaicos dentro de 2 grupos circundantes en cromáticos.",
  str_item_intro_9011030 = "Al inicio de cada ronda, los Aurorianos con menor HP se recuperan en proporción a su HP perdido.",
  str_item_intro_9011031 = "Al lograr la victoria en la batalla, todos los Aurorianos restauran el 20% de su HP.",
  str_item_intro_9011032 = "Si se obtienen Azulejos Oscuros en la ronda actual, gana 1 acumulación de Espíritu de Batalla.",
  str_item_intro_9011033 = "Los Aurorianos partidarios ganan 1 acumulación de Espíritu de Batalla al lanzar Habilidades Activas o Combos en Cadena para curar al equipo.",
  str_item_intro_9011034 = "Cuando las Habilidades Activas de los Aurorianos repelen o atraen a los enemigos, ganan acumulaciones de Espíritu de Batalla basadas en el número de objetivos afectados. Este efecto puede ser activado hasta 3 veces por ronda.",
  str_item_intro_9011035 = "Gana 1 acumulación de Espíritu de Batalla cada vez que los monstruos son afectados con Envenenamiento, Sangrado o Quemaduras. Este efecto puede ser activado hasta 4 veces por ronda.",
  str_item_intro_9011036 = "Gana Monedas de Sueño iguales a 4 veces el nivel cada vez que el Nivel de Sueño aumenta.",
  str_item_intro_9011037 = "Gana Monedas de Sueño iguales a 7 veces el incremento cada vez que el Interés de Sueño aumenta.",
  str_item_intro_9011038 = "Gana 4 Monedas de Sueño por cada Eclipsite derrotado en batalla.",
  str_item_intro_9011039 = "Uso único: Roba 5 Cartas de Adivinación de Sueños de tu mazo y obtiene Interés de Sueño igual a la suma de sus pasos.",
  str_item_intro_9011040 = "Obtén dos recompensas simultáneamente en el Reino del Sueño del Tesoro.",
  str_item_intro_9011041 = "Gana 30 EXP de Sueño cada vez que atraviesa un Reino de Sueño Peligroso.",
  str_item_intro_9011042 = "Disminuye los precios de los artículos que se pueden comprar y reduce el costo de volver a aleatorizar el Equipo de Sueño, los Aurorianos y los artículos en un 35%.",
  str_item_intro_9011043 = "Al adquirirlo, los Aurorians enviados a los Reinos de Sueños Inexplorados regresan inmediatamente, y la obtención de Monedas de Sueño e Intereses de Sueño de la expedición se duplican.",
  str_item_intro_9011044 = "Gana 40 Dream EXP cada vez que pasa por un campamento.",
  str_item_intro_9011045 = "Uso único: Todos los aurorianos pierden el 70% de su HP actual; ganan 25 EXP de Sueño por cada auroriano que pierde HP.",
  str_item_intro_9011046 = "Uso único: Consume la mitad de las Dream Coins actuales y obtiene 2 Dream EXP por cada Dream Coin consumida.",
  str_item_intro_9011047 = "Aumenta significativamente el daño de las Habilidades Activas de los Aurorianos; los Aurorianos pierden HP al infligir daño.",
  str_item_9011048 = "Bláster",
  str_item_9011049 = "Pisador",
  str_item_9011050 = "Matarreyes",
  str_item_9011051 = "Quiebra paredes",
  str_item_9011052 = "Paralizador",
  str_item_9011053 = "Golpeador de trueno",
  str_item_intro_9011048 = "Activa el <link=\"1005\"><color=#98500f><u>Módulo de Actualización de Algoritmo</u></color></link>; cuanto menos enemigos en el campo, mayor es el daño final.",
  str_item_intro_9011049 = "Activa el <link=\"1005\"><color=#98500f><u>Módulo de Actualización de Algoritmo</u></color></link>; El Capitán gana 3 <link=\"1006\"><color=#98500f><u>Puntos de Sobrecarga</u></color></link> al lanzar un ataque normal.",
  str_item_intro_9011050 = "Activa el <link=\"1005\"><color=#98500f><u>Módulo de Mejora de Algoritmo</u></color></link>; Habilidad Activa de Aurorians: genera 4 <link=\"1006\"><color=#98500f><u>Puntos de Sobrecarga</u></color></link> por cada enemigo golpeado.",
  str_item_intro_9011051 = "Activa el <link=\"1005\"><color=#98500f><u>Módulo de Actualización de Algoritmo</u></color></link>; al comienzo de la ronda, cuanto más bajo sea el PS del equipo, se obtienen más <link=\"1006\"><color=#98500f><u>Puntos de Sobrecarga</u></color></link>.",
  str_item_intro_9011052 = "Activa el <link=\"1005\"><color=#98500f><u>Módulo de Actualización de Algoritmo</u></color></link>; gana 8 <link=\"1006\"><color=#98500f><u>Puntos de Sobrecarga</u></color></link> cada vez que recibe daño.",
  str_item_intro_9011053 = "Activa el <link=\"1005\"><color=#98500f><u>Módulo de Mejora de Algoritmo</u></color></link>; aumenta el umbral de activación de la Bomba de Datos a 120 <link=\"1006\"><color=#98500f><u>Puntos de Sobrecarga</u></color></link>, infligiendo más daño a los monstruos de gran tamaño.",
  str_item_intro_9011054 = "Ya no ingresa a la Hora de Aurora; en cambio, gana +1ms de valor cada vez que se supone que debe ingresar a la Hora de Aurora, y recibe 5 de oro (la Hora de Aurora interrumpida por oleadas de monstruos o victoria en batalla también cuenta).",
  str_item_intro_9011055 = "Cuando un enemigo muere, convierte hasta 1 mosaico debajo de él en un Mosaico Oscuro.",
  str_item_intro_9011056 = "Al comienzo de la ronda, convierte las 2 fichas más cercanas del mismo elemento que el Capitán en Fichas Oscuras.",
  str_item_intro_9011057 = "Aumenta en 1 el número de opciones proporcionadas durante la selección de Equipo de Sueño.",
  str_item_intro_9011058 = "La primera actualización de las opciones de Dream Gear es gratis.",
  str_item_intro_9011059 = "Por cada pieza de Equipo de Sueño que poseas, aumenta el ATQ de los Aurorians Detonadores y Francotiradores en un 0.5%",
  str_item_intro_9011060 = "Por cada pieza de Equipo de Sueño que poseas, aumenta la DEF de los Aurorianos Conversores y Partidarios en un 2%.",
  str_item_intro_9011061 = "Por cada pieza de Equipo de Sueño que poseas, aumenta el Max HP de todos los Aurorianos en un 1.5%.",
  str_item_intro_9011062 = "Al inicio de cada ronda, genera 1 reloj (puede existir hasta 1 a la vez), reduciendo las rondas de enfriamiento de la habilidad del Aurorian con el mayor enfriamiento en 1.",
  str_item_intro_9011063 = "Inflige <link=\"1010\"><color=#98500f><u>Ceguera</u></color></link> a los objetivos que reciben daño.",
  str_item_intro_9011064 = "Cada vez que reciben daño, todos los Aurorians obtienen una bonificación de daño del 5%, hasta un máximo del 30% (se reinicia al final de la batalla).",
  str_item_intro_9011065 = "Aumenta el daño de los ataques normales en un 30%. Este efecto expira después de recibir daño.",
  str_item_intro_9011066 = "Reduce a la mitad la DEF de todos los Aurorianos y aumenta su propio ATK por la cantidad de DEF reducida.",
  str_item_intro_9011067 = "Genera una imagen del Capitán Aurorian en el punto de partida. Esta imagen también desata Chain Combos en esta ronda.",
  str_item_intro_9011068 = "Aumenta el daño en un 3.5% por cada Auroriano con diferentes Elementos Primarios en el equipo.",
  str_item_intro_9011069 = "Los elementos secundarios pueden infligir daño basado en el multiplicador de los elementos primarios, con un aumento adicional en el multiplicador cuando los elementos primarios y secundarios son los mismos.",
  str_item_intro_9011070 = "El Capitán anterior puede ser desplegado en batalla sin importar los elementos de las casillas conectadas.",
  str_item_intro_9011071 = "Capitán cambia las posibilidades +2 en cada batalla.\nAl cambiar de capitán, el tiempo de reutilización de la habilidad activa del nuevo capitán se reduce en 1. Cada auroriano solo puede activar este efecto una vez por ronda.",
  str_item_intro_9011072 = "Después de cada conexión o movimiento de casilla, la casilla inicial debe ser del mismo elemento que el del Capitán.",
  str_item_intro_9011073 = "Aumenta el daño infligido por todos los aliados en un 15%, pero convierte la casilla inicial de cada línea conectada en un mosaico roto que no se puede atravesar durante 8 rondas.",
  str_item_intro_9011074 = "Cuando las Habilidades Activas de los aurorianos repelen o atraen a un enemigo, infligen 3,000 de daño fijo por cada mosaico que recorre el objetivo.",
  str_item_intro_9011075 = "Todos los niveles de Avance de los Aurorians +1 (No aplica a los Aurorians cuyo nivel de Avance ha alcanzado el máximo).",
  str_item_intro_9011076 = "Uso único: Selecciona cualquier Aurorian para unirse al equipo; eleva el nivel de Avance de este Aurorian a su máximo.",
  str_item_intro_9011077 = "Los Aurorians Detonadores infligen 1 pila de <link=\"1003\"><color=#98500f><u>Fusión</u></color></link> al objetivo golpeado por sus Combos en Cadena.",
  str_item_intro_9011078 = "Las habilidades activas de los Aurorians Detonadores tienen un 40% de probabilidad de infligir <link=\"1011\"><color=#98500f><u>Parálisis</u></color></link> en el objetivo.",
  str_item_intro_9011079 = "Expande el rango de los Combos en Cadena de nivel más alto de los Aurorians Detonadores a 2 grupos.",
  str_item_intro_9011080 = "Los ataques normales de los Aurorians Detonadores infligen daño extra que ignora la DEF y además infligen daño equivalente al 10% de la PS perdida del Aurorian al objetivo.",
  str_item_intro_9011081 = "Los ataques normales de los Aurorianos Detonadores tienen un 30% de probabilidad de infligir un 150% de daño.",
  str_item_intro_9011082 = "Por cada Aurorian Detonador desplegado, aumenta el daño infligido por todos los Combos en Cadena de los Aurorians Detonadores en un 4%.",
  str_item_intro_9011083 = "Los ataques normales de los Aurorians Francotiradores infligen <link=\"1004\"><color=#98500f><u>Sabiduría</u></color></link> igual al 20% de su ATQ en los objetivos.",
  str_item_intro_9011084 = "Aumenta el daño infligido por los Combos en Cadena de los Aurorians Francotiradores a monstruos que ocupan múltiples casillas.",
  str_item_intro_9011085 = "Amplía el alcance de los Combos en Cadena de un solo objetivo de los Aurorians Francotiradores en 2 grupos y aumenta el número de objetivos en 1.",
  str_item_intro_9011086 = "Aumenta el daño de los Combos en Cadena de los Francotiradores Aurorianos en función de su HP perdido, con un aumento máximo del 50%.",
  str_item_intro_9011087 = "Las habilidades activas de los Aurorians Francotiradores tienen un 30% de probabilidad de infligir <link=\"1012\"><color=#98500f><u>Miedo</u></color></link> a los objetivos.",
  str_item_intro_9011088 = "Por cada Aurorian Francotirador desplegado, aumenta el daño infligido por los ataques normales de todos los Francotiradores Aurorianos en un 5%.",
  str_item_9810702 = "Mejora de algoritmo: Conjunto de equipo de sueño 2",
  str_item_9810704 = "Actualización de algoritmo: Conjunto de equipo de sueño 4",
  str_item_9810706 = "Mejora de Algoritmo: Conjunto de Equipo de Sueño 6",
  str_item_intro_9810702 = "Data Bomb inflige daño a un solo objetivo a todos los enemigos igual al 300% del ATK promedio del equipo.",
  str_item_intro_9810704 = "La Bomba de Datos inflige daño a un solo objetivo a todos los enemigos equivalente al 400% del ATK promedio del equipo.",
  str_item_intro_9810706 = "Data Bomb inflige daño a un solo objetivo a todos los enemigos equivalente al 500% del ATK promedio del equipo; cuanto mayor sea el porcentaje de HP del objetivo, mayor será el daño, hasta el doble.",
