  str_item_8800421 = "Receta de Colgante de Cobre",
  str_item_intro_8800103 = "Rocío tomado de la cumbre de los picos de cedro, tan puro que parece limpiar el espíritu de uno.",
  str_item_intro_8800102 = "Una flor que florece en el frío, exudando una fragancia tenue y delicada.",
  str_item_intro_8800101 = "Trozos de hielo omnipresentes que producen frío cuando se reúnen en grandes cantidades.",
  str_item_intro_8800203 = "Grasa picante y avanzada que encarna la pasión y el vigor de Rediesel.",
  str_item_intro_8800202 = "Piedras con aceite fundido corriendo por sus superficies.",
  str_item_intro_8800201 = "Granos ásperos de arena naranja, aún cálidos del desierto.",
  str_item_intro_8800303 = "Una rama frondosa, que fluye con una vitalidad asombrosa.",
  str_item_intro_8800302 = "Suave y aireado pelusa que esparce semillas de esperanza con el viento.",
  str_item_intro_8800301 = "Semillas verdes simples, esperando a brotar.",
  str_item_intro_8800403 = "Un cristal precioso y raro, brillando con la brillantez del amanecer.",
  str_item_intro_8800402 = "Una gema amarilla, chisporroteando con el poder del trueno.",
  str_item_intro_8800401 = "Un mineral discreto, algo más denso que las rocas habituales.",
  str_item_intro_8800113 = "Esencia nutritiva que vigoriza tanto a plantas como a animales.",
  str_item_intro_8800213 = "Tierno y dulce, cada bocado es un deleite.",
  str_item_intro_8800313 = "Una encantadora Muñeca Windelion con atractivo visual y placer táctil, con el potencial de ser un regalo popular.",
  str_item_intro_8800413 = "Una esfera de cristal que emite un brillo cautivador, ideal para la decoración del hogar.",
  str_item_intro_8800112 = "Un ungüento de acción rápida para esguinces y moretones. Es imprescindible para el hogar y los viajes.",
  str_item_intro_8800212 = "Minimiza la fricción y suaviza las superficies, adecuado para múltiples usos.",
  str_item_intro_8800312 = "Una vibrante y ecológica planta en maceta que prospera en lugares soleados.",
  str_item_intro_8800412 = "Un cuchillo increíblemente afilado. Corta todo con facilidad, preferido por los artesanos.",
  str_item_intro_8800111 = "Es adecuado para enfriar artículos y también seguro para beber.",
  str_item_intro_8800211 = "Explosivo de alta potencia que debe manejarse con precaución.",
  str_item_intro_8800311 = "Tela de cáñamo duradera y sencilla, adecuada para muchos propósitos.",
  str_item_intro_8800411 = "Un adorno modesto que exuda un encanto sutil.",
  str_item_intro_8800123 = "Una receta que detalla los requisitos para elaborar el Suplemento Nutricional.",
  str_item_intro_8800223 = "Una receta que detalla los requisitos para elaborar el Pastel Delicioso.",
  str_item_intro_8800323 = "Una receta que detalla los requisitos para elaborar la Muñeca Windelion Ornamental.",
  str_item_intro_8800423 = "Una receta que detalla los requisitos para elaborar el Adorno de Cristal.",
  str_item_intro_8800122 = "Una receta que detalla los requisitos para elaborar el Ungüento Externo.",
  str_item_intro_8800222 = "Una receta que detalla los requisitos para elaborar el Elixir Lubricante.",
  str_item_intro_8800322 = "Una receta que detalla los requisitos para elaborar la Planta Retenedora de Agua.",
  str_item_intro_8800422 = "Una receta que detalla los requisitos para fabricar el Cuchillo de Filo de Navaja.",
  str_item_intro_8800121 = "Una receta que detalla los requisitos para elaborar el Agua de Enfriamiento.",
  str_item_intro_8800221 = "Una receta que detalla los requisitos para fabricar el Bloque de Dinamita.",
  str_item_intro_8800321 = "Una receta que detalla los requisitos para elaborar la Tira de Arpillera.",
  str_item_intro_8800421 = "Una receta que detalla los requisitos para elaborar el Colgante de Cobre.",
  str_item_8800005 = "Fragmento antiguo",
  str_item_intro_8800005 = "Originalmente parte de una ruina, este fragmento de piedra está marcado por el paso del tiempo.",
  str_item_8800006 = "Transportador de Exploración",
  str_item_intro_8800006 = "Portador diseñado para la exploración de materiales de alquimia, con 2 unidades repuestas diariamente a las 05:00 de la hora del servidor.",
  str_item_8800008 = "Fondo de Atelier",
  str_item_intro_8800008 = "Ganancias del Mini Atelier. ¡Con la ayuda de Klaudia, esta tienda seguramente se hará un nombre en Astra!",
  str_item_8800010 = "AS",
  str_item_intro_8800010 = "Obtenido del trabajo diligente en el Mini Atelier, puede mejorar Amuletos y Trucos en el Árbol de Habilidades.",
  str_item_8800011 = "Caja de Materiales de Alquimia I",
